//! collab/mesh.rs —— 同账号设备网的**设备目录**(权威侧)。
//!
//! 解决的问题:此前接入一台远程主机要手工粘一串 PLRK1 连接码,N 台设备两两互连是 N² 次
//! 粘贴。Tailscale 的体验是「登录同一个账号 → 设备自己就成了网」。这张目录就是那个
//! 「自己成网」缺的一环:每台设备登录后把自己的 iroh NodeId 挂上来,同 uid 的其它设备
//! 拉一次清单就知道该连谁。
//!
//! **只有账号权威(云机)跑这张表。** 成员主机不存别人的设备,也不需要 —— 它们只是
//! 向权威报到、取清单。
//!
//! 凭据设计(这里是本模块唯一需要小心的地方):
//!  · 入网时权威颁一把**设备密钥**(32 字节随机),库里只留 sha256,明文只在颁发那一次回给设备。
//!  · 这把密钥能做两件事:报到取清单、以及**换取一张身份断言**。后者意味着它等同该账号的
//!    长期凭据 —— 所以按设备独立颁发、可按设备独立吊销,丢一台不必改密码。
//!  · 密钥**不用来直接访问别的设备**。设备之间进门仍走原来那条路:拿断言去对端换本机会话
//!    ([`super::authority::login_with_assertion`])。于是「谁能进我的机器」始终由**对端自己的
//!    成员资格**说了算,云机从不持有任何一台设备的访问权 —— 云机被拿下也开不了你家的盘。
use base64::Engine;
use rusqlite::{params, OptionalExtension};
use serde::Serialize;
use sha2::{Digest, Sha256};

use super::db::{self, now, open_db};

const B64: base64::engine::general_purpose::GeneralPurpose =
    base64::engine::general_purpose::URL_SAFE_NO_PAD;

/// 设备心跳周期(客户端 60s 一次)的 3 倍余量:超过这个没报到就算离线。
const ONLINE_WINDOW: i64 = 200;

#[derive(Serialize, Clone, Debug)]
pub struct Peer {
    pub node_id: String,
    pub name: String,
    pub os: String,
    pub ver: String,
    pub last_seen: i64,
    pub online: bool,
    /// 这台机器**第一次**入网的时刻。created_at 会被重登覆盖(同 NodeId 换密钥即 upsert),
    /// 留不住真正的首见时间,而设备台账要显示它 —— 「这台是三天前才冒出来的」是个安全信号。
    #[serde(default)]
    pub first_seen: i64,
}

fn hash_key(k: &str) -> String {
    let d = Sha256::digest(k.as_bytes());
    d.iter().map(|b| format!("{b:02x}")).collect()
}

fn new_key() -> Result<String, String> {
    let mut buf = [0u8; 32];
    getrandom::getrandom(&mut buf).map_err(|e| format!("生成设备密钥失败: {e}"))?;
    Ok(format!("mk_{}", B64.encode(buf)))
}

fn row_to_peer(
    r: &rusqlite::Row,
    t: i64,
) -> rusqlite::Result<Peer> {
    let last_seen: i64 = r.get(4)?;
    Ok(Peer {
        node_id: r.get(0)?,
        name: r.get(1)?,
        os: r.get(2)?,
        ver: r.get(3)?,
        last_seen,
        online: t - last_seen <= ONLINE_WINDOW,
        first_seen: r.get(5).unwrap_or(0),
    })
}

const PEER_COLS: &str = "node_id,name,os,ver,last_seen,first_seen";

/// 设备入网:登记 NodeId 并颁一把新的设备密钥(返回明文,只此一次)。
///
/// 同 node_id 再来 = **换一把新密钥**(重装、重新登录都走这条)。这是有意的幂等口径:
/// 一台机器的身份是它的 NodeId,不是密钥;重登不该在目录里堆出第二个「同一台机器」。
/// 顺带把 revoked 清零 —— 用户亲自重新登录进来,就是撤回了那次吊销。
pub fn enroll(uid: &str, node_id: &str, name: &str, os: &str, ver: &str) -> Result<String, String> {
    let node_id = node_id.trim();
    if node_id.is_empty() {
        return Err("设备缺 NodeId(本机 iroh 还没就绪,稍后重试)".into());
    }
    if uid.trim().is_empty() {
        return Err("缺账号 uid".into());
    }
    let key = new_key()?;
    let conn = open_db()?;
    // first_seen 用 excluded 会被重登覆盖 —— 这里刻意保留旧值(COALESCE 兜住老行的 0),
    // 因为台账要回答的是「这台机器什么时候第一次出现在我账号里」,不是「上次重登是几点」。
    conn.execute(
        "INSERT INTO mesh_nodes(node_id,uid,name,os,ver,key_hash,created_at,last_seen,revoked,first_seen) \
         VALUES(?1,?2,?3,?4,?5,?6,?7,?7,0,?7) \
         ON CONFLICT(node_id) DO UPDATE SET \
           uid=excluded.uid, name=excluded.name, os=excluded.os, ver=excluded.ver, \
           key_hash=excluded.key_hash, last_seen=excluded.last_seen, revoked=0, \
           first_seen=CASE WHEN mesh_nodes.first_seen>0 THEN mesh_nodes.first_seen ELSE excluded.first_seen END",
        params![node_id, uid.trim(), name.trim(), os.trim(), ver.trim(), hash_key(&key), now()],
    )
    .map_err(|e| format!("设备入网失败: {e}"))?;
    db::audit(uid, "mesh.enroll", node_id, name);
    Ok(key)
}

/// 设备密钥 → (uid, node_id)。吊销的、不认识的一律拒。
pub fn resolve_key(key: &str) -> Result<(String, String), String> {
    let conn = open_db()?;
    let row: Option<(String, String, i64)> = conn
        .query_row(
            "SELECT uid,node_id,revoked FROM mesh_nodes WHERE key_hash=?1",
            params![hash_key(key.trim())],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
        )
        .optional()
        .map_err(|e| format!("查设备失败: {e}"))?;
    match row {
        Some((_, _, revoked)) if revoked != 0 => {
            Err("这台设备已被移出设备网 —— 重新登录账号即可重新入网".into())
        }
        Some((uid, node_id, _)) => Ok((uid, node_id)),
        None => Err("设备密钥无效 —— 请重新登录账号入网".into()),
    }
}

/// 同一账号名下的其它设备(不含自己)。吊销的不出现在清单里。
pub fn peers(uid: &str, exclude_node: &str) -> Result<Vec<Peer>, String> {
    let t = now();
    let conn = open_db()?;
    let mut st = conn
        .prepare(&format!(
            "SELECT {PEER_COLS} FROM mesh_nodes \
             WHERE uid=?1 AND revoked=0 AND node_id<>?2 ORDER BY last_seen DESC"
        ))
        .map_err(|e| format!("查设备清单失败: {e}"))?;
    let rows = st
        .query_map(params![uid, exclude_node], |r| row_to_peer(r, t))
        .map_err(|e| format!("查设备清单失败: {e}"))?;
    Ok(rows.flatten().collect())
}

/// 设备**台账**:同一账号名下的全部设备,**含自己那台**,也含已被移出的。
///
/// 与 [`peers`] 的分工:那个是给对账循环用的「我该连谁」,所以排掉自己、排掉已吊销的;
/// 这个是给人看的,少一台都是缺陷 —— 用户要在台账上认出「哪台是我正在用的这台」,
/// 也要看见「上周被我踢掉的那台还在不在」。
pub fn devices(uid: &str) -> Result<Vec<(Peer, bool)>, String> {
    let t = now();
    let conn = open_db()?;
    let mut st = conn
        .prepare(&format!(
            "SELECT {PEER_COLS},revoked FROM mesh_nodes WHERE uid=?1 \
             ORDER BY revoked ASC, last_seen DESC"
        ))
        .map_err(|e| format!("查设备台账失败: {e}"))?;
    let rows = st
        .query_map(params![uid], |r| {
            Ok((row_to_peer(r, t)?, r.get::<_, i64>(6)? != 0))
        })
        .map_err(|e| format!("查设备台账失败: {e}"))?;
    Ok(rows.flatten().collect())
}

/// 给设备改个人话名字(台账上的「改名」)。
///
/// 为什么需要它:名字本来跟着 announce 走 = 机器名,一屋子 `DESKTOP-1D01IJR` 认不出谁是谁。
/// 改过名的设备打上 named 标记,此后 announce 不再用机器名覆盖它 —— 否则用户改完,
/// 下一拍心跳就给改回去了。
pub fn rename(uid: &str, node_id: &str, name: &str) -> Result<(), String> {
    let name = name.trim();
    if name.is_empty() || name.chars().count() > 40 {
        return Err("设备名长度须为 1–40 个字符".into());
    }
    let conn = open_db()?;
    let n = conn
        .execute(
            "UPDATE mesh_nodes SET name=?3 WHERE node_id=?1 AND uid=?2",
            params![node_id.trim(), uid, name],
        )
        .map_err(|e| format!("改设备名失败: {e}"))?;
    if n == 0 {
        return Err("这台设备不在你账号的设备网里".into());
    }
    // 记住「这个名字是人取的」,announce 从此不覆盖它。
    let _ = conn.execute(
        "INSERT INTO meta(k,v) VALUES(?1,'1') ON CONFLICT(k) DO UPDATE SET v='1'",
        params![named_key(node_id)],
    );
    db::audit(uid, "mesh.rename", node_id.trim(), name);
    Ok(())
}

/// 「这台设备的名字是人手取的」标记键。
fn named_key(node_id: &str) -> String {
    format!("mesh_named_{}", node_id.trim())
}

/// 心跳 + 取清单(一次往返办两件事:设备网的轮询频率不低,能省一趟就省一趟)。
pub fn announce(key: &str, name: &str, os: &str, ver: &str) -> Result<(String, Vec<Peer>), String> {
    let (uid, node_id) = resolve_key(key)?;
    let conn = open_db()?;
    // 用户在台账上手工改过名的设备,心跳不许再拿机器名覆盖回去 ——
    // 否则「改名」这个动作最多活 60 秒,下一拍就被打回原形。
    let human_named = db::meta_get(&named_key(&node_id)).as_deref() == Some("1");
    let name = if human_named { "" } else { name };
    // 名字/版本每次报到都跟着更新:改了机器名、升了版本,清单里立刻是新的。
    conn.execute(
        "UPDATE mesh_nodes SET last_seen=?1, \
           name=CASE WHEN ?2<>'' THEN ?2 ELSE name END, \
           os=CASE WHEN ?3<>'' THEN ?3 ELSE os END, \
           ver=CASE WHEN ?4<>'' THEN ?4 ELSE ver END \
         WHERE node_id=?5",
        params![now(), name.trim(), os.trim(), ver.trim(), node_id],
    )
    .map_err(|e| format!("设备报到失败: {e}"))?;
    let list = peers(&uid, &node_id)?;
    Ok((uid, list))
}

/// 把自己账号名下的一台设备移出设备网(丢了电脑的应急操作)。
/// 只能踢**同 uid** 的设备 —— 拿着自己的密钥踢不掉别人账号的机器。
pub fn revoke(uid: &str, node_id: &str) -> Result<(), String> {
    let conn = open_db()?;
    let n = conn
        .execute(
            "UPDATE mesh_nodes SET revoked=1 WHERE node_id=?1 AND uid=?2",
            params![node_id.trim(), uid],
        )
        .map_err(|e| format!("移出设备网失败: {e}"))?;
    if n == 0 {
        return Err("这台设备不在你账号的设备网里".into());
    }
    db::audit(uid, "mesh.revoke", node_id, "");
    Ok(())
}

/// uid → (username, email, display_name)。给设备换取身份断言时填断言载荷用。
pub fn account_of(uid: &str) -> Result<(String, String, String), String> {
    let conn = open_db()?;
    conn.query_row(
        "SELECT username,email,display_name,disabled FROM users WHERE uid=?1",
        params![uid],
        |r| {
            Ok((
                r.get::<_, String>(0)?,
                r.get::<_, String>(1)?,
                r.get::<_, String>(2)?,
                r.get::<_, i64>(3)?,
            ))
        },
    )
    .optional()
    .map_err(|e| format!("查账号失败: {e}"))?
    .ok_or_else(|| "这个账号在账号中心已不存在".to_string())
    .and_then(|(u, e, d, disabled)| {
        if disabled != 0 {
            Err("账号已停用".into())
        } else {
            Ok((u, e, d))
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp_db(tag: &str) -> std::sync::MutexGuard<'static, ()> {
        let g = db::TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let p = std::env::temp_dir().join(format!("mesh-test-{}-{tag}.db", std::process::id()));
        let _ = std::fs::remove_file(&p);
        std::env::set_var("POLARIS_COLLAB_DB", &p);
        g
    }

    /// 入网 → 报到 → 互见:两台设备同一个 uid,各自只看见对方。
    #[test]
    fn two_devices_of_one_account_see_each_other() {
        let _g = tmp_db("pair");
        let k1 = enroll("acct_1", "node-aaa", "台式机", "windows", "2.6.0").unwrap();
        let k2 = enroll("acct_1", "node-bbb", "NAS", "linux", "2.6.0").unwrap();
        assert_ne!(k1, k2, "每台设备一把独立密钥");

        let (uid, p1) = announce(&k1, "台式机", "windows", "2.6.0").unwrap();
        assert_eq!(uid, "acct_1");
        assert_eq!(p1.len(), 1, "只该看见对方一台");
        assert_eq!(p1[0].node_id, "node-bbb");
        assert!(p1[0].online, "刚报到过必须算在线");

        let (_, p2) = announce(&k2, "NAS", "linux", "2.6.0").unwrap();
        assert_eq!(p2[0].node_id, "node-aaa");
    }

    /// 账号隔离:别人账号的设备绝不出现在我的清单里。
    #[test]
    fn other_accounts_are_invisible() {
        let _g = tmp_db("iso");
        let mine = enroll("acct_me", "node-mine", "我的", "windows", "1").unwrap();
        enroll("acct_other", "node-other", "别人的", "linux", "1").unwrap();
        let (_, list) = announce(&mine, "", "", "").unwrap();
        assert!(list.is_empty(), "看见了不属于本账号的设备:{list:?}");
    }

    /// 吊销即失效:密钥不能再报到;本人重新登录(再 enroll)可自助恢复。
    #[test]
    fn revoke_then_reenroll() {
        let _g = tmp_db("revoke");
        let k = enroll("acct_1", "node-x", "旧机", "windows", "1").unwrap();
        enroll("acct_1", "node-y", "另一台", "windows", "1").unwrap();

        revoke("acct_1", "node-x").unwrap();
        assert!(announce(&k, "", "", "").is_err(), "吊销后不该还能报到");
        // 别人的账号踢不动我的设备。
        assert!(revoke("acct_other", "node-y").is_err());

        // 重新入网:拿到新密钥,旧密钥永久作废。
        let k2 = enroll("acct_1", "node-x", "旧机", "windows", "1").unwrap();
        assert!(announce(&k2, "", "", "").is_ok());
        assert!(announce(&k, "", "", "").is_err(), "旧密钥必须仍然无效");
    }

    /// 重复入网不制造重影:同一台机器登两次,目录里仍是一台。
    #[test]
    fn reenroll_is_idempotent_on_node_id() {
        let _g = tmp_db("dup");
        enroll("acct_1", "node-a", "机器", "windows", "1").unwrap();
        let k = enroll("acct_1", "node-a", "机器改了名", "windows", "2").unwrap();
        enroll("acct_1", "node-b", "另一台", "linux", "1").unwrap();
        let (_, list) = announce(&k, "", "", "").unwrap();
        assert_eq!(list.len(), 1, "同 node_id 重复入网不该多出一台:{list:?}");
    }

    /// 台账:含自己、含已移出的;改过名之后心跳不许把名字打回原形。
    #[test]
    fn ledger_lists_all_and_keeps_human_names() {
        let _g = tmp_db("ledger");
        let k1 = enroll("acct_1", "node-a", "DESKTOP-1D01IJR", "windows", "2.9.0").unwrap();
        enroll("acct_1", "node-b", "NAS", "linux", "2.9.0").unwrap();
        enroll("acct_1", "node-c", "旧笔记本", "windows", "2.7.0").unwrap();
        revoke("acct_1", "node-c").unwrap();

        let list = devices("acct_1").unwrap();
        assert_eq!(list.len(), 3, "台账要含自己那台和已移出的那台:{list:?}");
        assert!(list.iter().any(|(p, rev)| p.node_id == "node-c" && *rev));
        assert!(list.iter().all(|(p, _)| p.first_seen > 0), "首见时刻要落下来");

        // 改名 → 心跳带着机器名再来一次 → 名字必须还是人取的那个。
        rename("acct_1", "node-a", "书房台式机").unwrap();
        announce(&k1, "DESKTOP-1D01IJR", "windows", "2.9.0").unwrap();
        let list = devices("acct_1").unwrap();
        let a = list.iter().find(|(p, _)| p.node_id == "node-a").unwrap();
        assert_eq!(a.0.name, "书房台式机", "手工改的名被心跳覆盖了");

        // 改不了别人账号的设备名。
        assert!(rename("acct_other", "node-a", "偷改").is_err());
        assert!(rename("acct_1", "node-a", "").is_err());
    }

    /// 重复入网不该把「第一次见到这台机器」的时刻冲掉(安全信号要留得住)。
    #[test]
    fn first_seen_survives_reenroll() {
        let _g = tmp_db("firstseen");
        enroll("acct_1", "node-a", "机器", "windows", "1").unwrap();
        let first = devices("acct_1").unwrap()[0].0.first_seen;
        assert!(first > 0);
        std::thread::sleep(std::time::Duration::from_millis(1100));
        enroll("acct_1", "node-a", "机器", "windows", "2").unwrap();
        assert_eq!(devices("acct_1").unwrap()[0].0.first_seen, first);
    }

    #[test]
    fn bad_key_is_refused() {
        let _g = tmp_db("badkey");
        enroll("acct_1", "node-a", "机器", "windows", "1").unwrap();
        assert!(resolve_key("mk_totally-made-up").is_err());
        assert!(announce("", "", "", "").is_err());
    }
}

//! collab/grants.rs —— 设备信任契约(`peer_grants`)。
//!
//! 解决的是「记住权限的状态」这件事。此前的实际行为是:每次重连都重新握手、重新问一遍
//! 能不能挂盘,而挂载配置只活在 fsmount 的内存态里 —— 重启一次全忘光,用户要重新点一遍。
//! 这张表记的是**用户的意图**(我批准了这台设备、批到什么档、要不要自动挂盘),不是运行态,
//! 所以它跨重启、跨换网、跨换 IP 都成立。
//!
//! 一行契约同时服务两个方向 —— 它描述的是「我和这台设备之间的信任」,不是单向配置:
//!  · **出方向**:后台对账循环据此决定连不连它、挂不挂盘、挂只读还是可读写。
//!  · **入方向**:它拿断言来进本机门时,`revoked=1` 直接拒 —— 这是云端目录之外的第二道闸,
//!    云机被绕过、名册被伪造,本机这一行仍然说了算。
//!
//! ## 冷静期(cooldown)
//!
//! `SelfOwned` 准入让「同一个账号的设备免邀请码」,代价是:云机若被拿下,伪造一张断言就能
//! 直接成为你每台机器的 owner。冷静期是这一让步的对冲 —— 一台**从没见过的**新设备首次进来,
//! 24 小时内一律按只读对待,且这段时间里用户能一键撤销。把「静默拿到全权」压成
//! 「24 小时内可反悔的只读」。用户在设备台账上点「信任这台设备」即当场清零。
//!
//! 注意冷静期只对**账号里已经有别的设备**时生效:第一台设备就是你本人在装机,拦它没有意义,
//! 只会让「填个邮箱就能用」变成「填完还要等一天」。
use rusqlite::{params, OptionalExtension};
use serde::Serialize;

use super::db::{self, now, open_db};

/// 新设备冷静期时长(秒)。
pub const COOLDOWN_SECS: i64 = 24 * 3600;

/// 盘访问档。
pub const FS_NONE: &str = "none";
pub const FS_RO: &str = "ro";
pub const FS_RW: &str = "rw";

/// 远程执行档。
pub const EXEC_NONE: &str = "none";
pub const EXEC_ASK: &str = "ask";
pub const EXEC_ALLOW: &str = "allow";

#[derive(Serialize, Clone, Debug, PartialEq)]
pub struct Grant {
    pub node_id: String,
    pub uid: String,
    pub name: String,
    pub role: String,
    /// 库里存的档位(用户批的那个)。实际生效的档见 [`Grant::effective_fs`]。
    pub fs_access: String,
    pub exec_access: String,
    pub auto_mount: bool,
    pub drive_hint: String,
    pub cooldown_until: i64,
    pub granted_at: i64,
    pub granted_by: String,
    pub revoked: bool,
}

impl Grant {
    /// 冷静期内还在观察的新设备:UI 要显著提示,用户据此决定信任还是撤销。
    pub fn in_cooldown(&self) -> bool {
        self.cooldown_until > now()
    }

    /// **实际**生效的盘访问档。冷静期内一律降到只读 —— 这就是那句「可反悔的只读」
    /// 落在代码里的样子:库里记着用户批的 rw,但这 24 小时内谁问都只给 ro。
    pub fn effective_fs(&self) -> &str {
        if self.revoked {
            return FS_NONE;
        }
        if self.in_cooldown() && self.fs_access == FS_RW {
            return FS_RO;
        }
        &self.fs_access
    }

    /// 实际生效的执行档。冷静期内不给 allow(降到 ask,由人当场确认)。
    pub fn effective_exec(&self) -> &str {
        if self.revoked {
            return EXEC_NONE;
        }
        if self.in_cooldown() && self.exec_access == EXEC_ALLOW {
            return EXEC_ASK;
        }
        &self.exec_access
    }

    /// 这台设备现在该不该被自动连上并挂盘。
    pub fn should_mount(&self) -> bool {
        !self.revoked && self.auto_mount && self.effective_fs() != FS_NONE
    }
}

fn norm_fs(v: &str) -> Result<&'static str, String> {
    match v.trim() {
        FS_NONE => Ok(FS_NONE),
        FS_RO => Ok(FS_RO),
        FS_RW => Ok(FS_RW),
        other => Err(format!("盘访问档只能是 none/ro/rw,收到「{other}」")),
    }
}

fn norm_exec(v: &str) -> Result<&'static str, String> {
    match v.trim() {
        EXEC_NONE => Ok(EXEC_NONE),
        EXEC_ASK => Ok(EXEC_ASK),
        EXEC_ALLOW => Ok(EXEC_ALLOW),
        other => Err(format!("执行档只能是 none/ask/allow,收到「{other}」")),
    }
}

fn row_to_grant(r: &rusqlite::Row) -> rusqlite::Result<Grant> {
    Ok(Grant {
        node_id: r.get(0)?,
        uid: r.get(1)?,
        name: r.get(2)?,
        role: r.get(3)?,
        fs_access: r.get(4)?,
        exec_access: r.get(5)?,
        auto_mount: r.get::<_, i64>(6)? != 0,
        drive_hint: r.get(7)?,
        cooldown_until: r.get(8)?,
        granted_at: r.get(9)?,
        granted_by: r.get(10)?,
        revoked: r.get::<_, i64>(11)? != 0,
    })
}

const COLS: &str = "node_id,uid,name,role,fs_access,exec_access,auto_mount,drive_hint,\
                    cooldown_until,granted_at,granted_by,revoked";

/// 查一台设备的契约。没批过 = None。
pub fn get(node_id: &str) -> Result<Option<Grant>, String> {
    let node_id = node_id.trim();
    if node_id.is_empty() {
        return Ok(None);
    }
    let conn = open_db()?;
    conn.query_row(
        &format!("SELECT {COLS} FROM peer_grants WHERE node_id=?1"),
        params![node_id],
        row_to_grant,
    )
    .optional()
    .map_err(|e| format!("查设备契约失败: {e}"))
}

/// 全部契约(含已撤销的 —— 台账要能看见「这台被我踢过」)。
pub fn list() -> Result<Vec<Grant>, String> {
    let conn = open_db()?;
    let mut st = conn
        .prepare(&format!(
            "SELECT {COLS} FROM peer_grants ORDER BY revoked ASC, granted_at DESC"
        ))
        .map_err(|e| format!("查设备契约失败: {e}"))?;
    let rows = st
        .query_map([], row_to_grant)
        .map_err(|e| format!("查设备契约失败: {e}"))?;
    Ok(rows.flatten().collect())
}

/// 首次见到一台**自己账号的**设备时自动批准。
///
/// 返回 (契约, 是否新建)。已存在就原样返回 —— 用户后来手工调过的档位,不能被一次重连覆盖回默认值,
/// 那等于「每次重启都把权限重置一遍」,正是这次要修掉的毛病。
///
/// `is_first_device=true`(本机此前一台设备都没批过)时不设冷静期:那就是你本人在装第一台机器,
/// 拦它只会把「填个邮箱就能用」变成「填完还要等一天」。
pub fn auto_grant_self(
    node_id: &str,
    uid: &str,
    name: &str,
    is_first_device: bool,
) -> Result<(Grant, bool), String> {
    let node_id = node_id.trim();
    if node_id.is_empty() {
        return Err("缺 NodeId".into());
    }
    if let Some(g) = get(node_id)? {
        return Ok((g, false));
    }
    let t = now();
    let cooldown = if is_first_device {
        0
    } else {
        t + COOLDOWN_SECS
    };
    let conn = open_db()?;
    conn.execute(
        "INSERT INTO peer_grants(node_id,uid,name,role,fs_access,exec_access,auto_mount,\
         drive_hint,cooldown_until,granted_at,granted_by,revoked) \
         VALUES(?1,?2,?3,'owner',?4,?5,1,'',?6,?7,'auto:same-account',0)",
        params![
            node_id,
            uid.trim(),
            name.trim(),
            FS_RW,
            EXEC_ALLOW,
            cooldown,
            t
        ],
    )
    .map_err(|e| format!("登记设备契约失败: {e}"))?;
    db::audit(
        uid,
        "peer.grant.auto",
        node_id,
        if cooldown > 0 {
            "同账号设备·冷静期中"
        } else {
            "同账号设备·首台"
        },
    );
    Ok((get(node_id)?.ok_or("刚写入的契约读不回来")?, true))
}

/// 用户在设备台账上改档位。只改传进来的字段(None = 不动)。
#[allow(clippy::too_many_arguments)]
pub fn update(
    node_id: &str,
    name: Option<&str>,
    fs_access: Option<&str>,
    exec_access: Option<&str>,
    auto_mount: Option<bool>,
    actor: &str,
) -> Result<Grant, String> {
    let node_id = node_id.trim();
    let cur = get(node_id)?.ok_or("这台设备还没有信任契约")?;
    let fs = match fs_access {
        Some(v) => norm_fs(v)?.to_string(),
        None => cur.fs_access.clone(),
    };
    let ex = match exec_access {
        Some(v) => norm_exec(v)?.to_string(),
        None => cur.exec_access.clone(),
    };
    let nm = name
        .map(|s| s.trim().to_string())
        .unwrap_or(cur.name.clone());
    let am = auto_mount.unwrap_or(cur.auto_mount);
    let conn = open_db()?;
    conn.execute(
        "UPDATE peer_grants SET name=?2, fs_access=?3, exec_access=?4, auto_mount=?5, \
         granted_by=?6 WHERE node_id=?1",
        params![node_id, nm, fs, ex, i64::from(am), actor],
    )
    .map_err(|e| format!("改设备契约失败: {e}"))?;
    db::audit(
        actor,
        "peer.grant.update",
        node_id,
        &format!("fs={fs} exec={ex} auto={am}"),
    );
    get(node_id)?.ok_or_else(|| "改完读不回来".into())
}

/// 用户点「信任这台设备」:冷静期立即清零。
pub fn trust_now(node_id: &str, actor: &str) -> Result<Grant, String> {
    let node_id = node_id.trim();
    let conn = open_db()?;
    let n = conn
        .execute(
            "UPDATE peer_grants SET cooldown_until=0, revoked=0 WHERE node_id=?1",
            params![node_id],
        )
        .map_err(|e| format!("信任设备失败: {e}"))?;
    if n == 0 {
        return Err("这台设备还没有信任契约".into());
    }
    db::audit(actor, "peer.grant.trust", node_id, "冷静期已清零");
    get(node_id)?.ok_or_else(|| "改完读不回来".into())
}

/// 撤销一台设备的准入(丢了电脑 / 冷静期内反悔)。
/// 幂等:没批过也当成功 —— 用户的意图是「这台不许进」,而它本来就进不来。
pub fn revoke(node_id: &str, actor: &str) -> Result<(), String> {
    let node_id = node_id.trim();
    if node_id.is_empty() {
        return Err("缺 NodeId".into());
    }
    let conn = open_db()?;
    conn.execute(
        "INSERT INTO peer_grants(node_id,granted_at,revoked) VALUES(?1,?2,1) \
         ON CONFLICT(node_id) DO UPDATE SET revoked=1",
        params![node_id, now()],
    )
    .map_err(|e| format!("撤销设备失败: {e}"))?;
    db::audit(actor, "peer.grant.revoke", node_id, "");
    Ok(())
}

/// 记住这台设备上次挂成了哪个盘符(下次尽量复原,免得每次重启换个字母,
/// 用户存的快捷方式、脚本里的路径全断)。
pub fn remember_drive(node_id: &str, drive: &str) -> Result<(), String> {
    let conn = open_db()?;
    conn.execute(
        "UPDATE peer_grants SET drive_hint=?2 WHERE node_id=?1",
        params![node_id.trim(), drive.trim()],
    )
    .map_err(|e| format!("记盘符失败: {e}"))?;
    Ok(())
}

/// 本机此前批过设备没有(判「是不是第一台」用)。
pub fn any_granted() -> Result<bool, String> {
    let conn = open_db()?;
    let n: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM peer_grants WHERE revoked=0",
            [],
            |r| r.get(0),
        )
        .map_err(|e| format!("查设备契约失败: {e}"))?;
    Ok(n > 0)
}

/// 入方向的闸:这台设备被撤销过吗。
/// **只认已撤销**,不认「没有契约」—— 没契约的设备走的是别的门(邀请码/首登建 owner),
/// 那些路各有各的判定,这里越权拒绝会把正常的首次登录也堵死。
pub fn is_revoked(node_id: &str) -> bool {
    matches!(get(node_id), Ok(Some(g)) if g.revoked)
}

// ───────────────────────── 入方向:按设备放行 ─────────────────────────
//
// 在此之前这张表**只在出方向消费**(本机挂对端的盘时定 ro/rw),入方向只判了一个
// `revoked`。也就是说台账上那两排「盘:只读/读写」「远程执行:禁止/每次问/允许」
// 对**连进来的人**根本不生效 —— 进得来就是 owner 全权。设备码这条路一旦开放,
// 那等于「谁拿到码谁就能删你的盘」。下面两道闸把台账上的档位变成真的。
//
// 判定顺序刻意如此:
//  ① 没有 device_id(全局口令 admin / 老会话 / 本机内部调用)→ 放行,交给原来的角色闸。
//     这条是为了**不破坏现状**:桌面自己、owner 令牌、CI 探针走的都是这条。
//  ② device_id 就是本机自己 → 放行。桌面登录时会话上记的是本机 NodeId,而本机
//     也给自己建了一行契约;要是让它受契约约束,本机排在「第二台设备」时会被自己的
//     24 小时冷静期降成只读 —— 自己把自己锁了。
//  ③ 有契约 → 契约说了算(冷静期/撤销都已经折进 effective_*)。
//  ④ 有 device_id 但没契约 → 放行,交给角色闸。没契约的是「还没走过设备码那条路」的
//     老客户端(手机壳粘 PLRK1 之类),它们本来就要过 owner 闸,这里不额外收紧。

/// 本机自己那台设备的 NodeId。空 = 隧道还没起过(那时也不会有对端进来)。
fn my_node() -> String {
    db::meta_get("host_node_id").unwrap_or_default()
}

/// 这个 device_id 是不是「不受契约约束」的自己人(见上面的 ①②④)。
fn exempt(device_id: &str) -> bool {
    let d = device_id.trim();
    if d.is_empty() {
        return true;
    }
    let me = my_node();
    !me.is_empty() && me == d
}

/// **盘闸**:这台设备能不能读 / 能不能写本机共享出去的目录。
/// 拒绝时回的是人话 —— 它会一路透到对方的资源管理器里当失败原因显示。
pub fn fs_gate(device_id: &str, need_write: bool) -> Result<(), String> {
    if exempt(device_id) {
        return Ok(());
    }
    let Some(g) = get(device_id).unwrap_or(None) else {
        return Ok(());
    };
    match g.effective_fs() {
        FS_RW => Ok(()),
        FS_RO if !need_write => Ok(()),
        FS_RO => Err(if g.in_cooldown() {
            "这台设备还在新设备观察期内,暂时只读 —— 在对方机器的「设备与授权」里点「信任这台」即可写"
                .into()
        } else {
            "对方把这台设备设成了只读 —— 请他在「设备与授权」里把盘改成「可读写」".into()
        }),
        _ => Err(if g.revoked {
            "这台设备已被对方移出信任列表".into()
        } else {
            "对方没有把盘开放给这台设备(当前档位:不挂盘)".into()
        }),
    }
}

/// **执行闸**:这台设备能不能在本机跑命令。`ask` 当前按拒处理 ——
/// 「每次问」需要一条弹窗确认通道,那条通道还没有;在它到位之前宁可拒,
/// 也不能把一个中间档静默当成「允许」。
pub fn exec_gate(device_id: &str) -> Result<(), String> {
    if exempt(device_id) {
        return Ok(());
    }
    let Some(g) = get(device_id).unwrap_or(None) else {
        return Ok(());
    };
    match g.effective_exec() {
        EXEC_ALLOW => Ok(()),
        EXEC_ASK if g.in_cooldown() => {
            Err("这台设备还在新设备观察期内,暂不允许远程执行 —— 对方点一下「信任这台」即可".into())
        }
        EXEC_ASK => Err(
            "对方把这台设备的远程执行设成了「每次问」,而本机还没有弹窗确认通道 —— 请他改成「允许」"
                .into(),
        ),
        _ => Err("对方没有允许这台设备远程执行(当前档位:禁止)".into()),
    }
}

/// 拿**设备码**连进来的对端:默认只读、禁执行、不自动挂盘。
///
/// 与 [`auto_grant_self`] 的区别正是「这是别人」——后者是同一个账号的自己人,默认全权;
/// 这里默认最小权限,由本机主人在台账上点「信任这台」再升档。已有契约原样沿用
/// (用户调过的档不能被对方重连一次冲回默认值),已撤销的直接拒。
pub fn grant_by_code(node_id: &str, name: &str) -> Result<Grant, String> {
    let node_id = node_id.trim();
    if node_id.is_empty() {
        return Err("缺 NodeId".into());
    }
    if let Some(g) = get(node_id)? {
        if g.revoked {
            return Err(
                "这台设备已被移出本机的信任列表 —— 请机主先在「设备与授权」里恢复它".into(),
            );
        }
        return Ok(g);
    }
    let t = now();
    let conn = open_db()?;
    conn.execute(
        "INSERT INTO peer_grants(node_id,uid,name,role,fs_access,exec_access,auto_mount,\
         drive_hint,cooldown_until,granted_at,granted_by,revoked) \
         VALUES(?1,'',?2,'visitor',?3,?4,0,'',0,?5,?6,0)",
        params![node_id, name.trim(), FS_RO, EXEC_NONE, t, BY_CODE],
    )
    .map_err(|e| format!("登记设备契约失败: {e}"))?;
    db::audit("system", "peer.grant.code", node_id, "设备码接入·默认只读");
    get(node_id)?.ok_or_else(|| "刚写入的契约读不回来".into())
}

/// `granted_by` 上标记「这一行是拿设备码进来的」。换码时要按它把旧会话清干净。
pub const BY_CODE: &str = "code";

/// 「信任这台设备」的完整含义:冷静期清零 + 升到全权。
///
/// 为什么不复用 [`trust_now`]:那个只清冷静期,对**设备码**进来的设备毫无作用 ——
/// 它压根没有冷静期,它的限制是 `fs=ro/exec=none` 这两个档位本身。用户点的那颗按钮
/// 心里想的是「这台我认了,放开」,所以两件事必须一起做。
pub fn trust_fully(node_id: &str, actor: &str) -> Result<Grant, String> {
    let node_id = node_id.trim();
    if get(node_id)?.is_none() {
        return Err("这台设备还没有信任契约".into());
    }
    let conn = open_db()?;
    // `granted_by` 同时记着准入来源。靠设备码进来的行必须一直保留 `code`，否则机主
    // 点一次「信任这台」后再换码，rotate_access_code 就找不到并吊销它的旧会话。
    conn.execute(
        "UPDATE peer_grants SET cooldown_until=0, revoked=0, fs_access=?2, exec_access=?3, \
         auto_mount=1 WHERE node_id=?1",
        params![node_id, FS_RW, EXEC_ALLOW],
    )
    .map_err(|e| format!("信任设备失败: {e}"))?;
    db::audit(actor, "peer.grant.trust", node_id, "已升为全权");
    get(node_id)?.ok_or_else(|| "改完读不回来".into())
}

#[cfg(test)]
mod gate_tests {
    use super::*;

    fn tmp(tag: &str) -> std::sync::MutexGuard<'static, ()> {
        let g = db::TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        std::env::set_var(
            "POLARIS_COLLAB_DB",
            std::env::temp_dir().join(format!(
                "grants-gate-{tag}-{}-{}.db",
                std::process::id(),
                now()
            )),
        );
        g
    }

    /// 设备码进来的对端:**默认只读、禁执行**。这是用户拍板的那一档。
    #[test]
    fn code_peer_is_read_only_until_trusted() {
        let _g = tmp("code");
        let peer = "node-someone-else";
        let created = grant_by_code(peer, "小李的笔记本").unwrap();
        assert_eq!(created.fs_access, FS_RO);
        assert_eq!(created.exec_access, EXEC_NONE);
        assert!(!created.auto_mount, "别人的设备不该自动挂进我的盘符");

        assert!(fs_gate(peer, false).is_ok(), "读要放行");
        let e = fs_gate(peer, true).unwrap_err();
        assert!(e.contains("只读"), "写必须被挡住,err={e}");
        assert!(exec_gate(peer).unwrap_err().contains("禁止"));

        // 机主点「信任这台」→ 一步升到全权。
        trust_fully(peer, "本机").unwrap();
        assert!(fs_gate(peer, true).is_ok());
        assert!(exec_gate(peer).is_ok());
    }

    /// 重连不能把机主调过的档冲回默认值 —— 那等于「每次重连权限重置一遍」。
    #[test]
    fn reconnect_keeps_the_owner_decision() {
        let _g = tmp("keep");
        grant_by_code("node-p", "对方").unwrap();
        trust_fully("node-p", "本机").unwrap();
        let again = grant_by_code("node-p", "对方").unwrap();
        assert_eq!(again.fs_access, FS_RW, "重连不该把 rw 冲回 ro");
        // 反过来也一样:降成不挂盘之后,对方重连仍是不挂盘。
        update("node-p", None, Some(FS_NONE), None, None, "本机").unwrap();
        assert_eq!(grant_by_code("node-p", "对方").unwrap().fs_access, FS_NONE);
        assert!(fs_gate("node-p", false).unwrap_err().contains("不挂盘"));
    }

    /// 踢掉的设备拿着旧码回来也进不去。
    #[test]
    fn revoked_peer_cannot_reconnect_with_the_code() {
        let _g = tmp("revoked");
        grant_by_code("node-bad", "谁").unwrap();
        revoke("node-bad", "本机").unwrap();
        assert!(grant_by_code("node-bad", "谁")
            .unwrap_err()
            .contains("移出"));
        assert!(fs_gate("node-bad", false).is_err());
        assert!(exec_gate("node-bad").is_err());
    }

    /// 本机自己不受契约约束:桌面会话上记的是本机 NodeId,而本机也给自己建了一行契约。
    /// 要是让它受约束,本机排在「第二台设备」时会被自己的 24 小时冷静期降成只读 —— 自锁。
    #[test]
    fn my_own_machine_is_never_gated_by_its_own_grant() {
        let _g = tmp("self");
        db::meta_set("host_node_id", "node-me").unwrap();
        // 造一行最严的契约扣在自己头上。
        grant_by_code("node-me", "我自己").unwrap();
        update(
            "node-me",
            None,
            Some(FS_NONE),
            Some(EXEC_NONE),
            None,
            "本机",
        )
        .unwrap();
        assert!(fs_gate("node-me", true).is_ok(), "本机不该被自己的契约锁住");
        assert!(exec_gate("node-me").is_ok());
        // 空 device_id(全局口令 / 老会话 / 本机内部调用)同样豁免。
        assert!(fs_gate("", true).is_ok());
        assert!(exec_gate("").is_ok());
    }

    /// 没有契约的设备不额外收紧 —— 老手机壳粘 PLRK1 那条路仍旧只过角色闸。
    #[test]
    fn unknown_device_falls_back_to_the_role_gate() {
        let _g = tmp("unknown");
        db::meta_set("host_node_id", "node-me").unwrap();
        assert!(fs_gate("node-never-seen", true).is_ok());
        assert!(exec_gate("node-never-seen").is_ok());
    }

    /// 同账号设备的冷静期在**入方向**也真的生效了(此前只影响本机挂对端时的 ro/rw)。
    #[test]
    fn same_account_cooldown_now_bites_on_the_way_in() {
        let _g = tmp("cooldown");
        db::meta_set("host_node_id", "node-me").unwrap();
        auto_grant_self("node-first", "acct_1", "第一台", true).unwrap();
        let (second, _) = auto_grant_self("node-2nd", "acct_1", "新来的", false).unwrap();
        assert!(second.in_cooldown());
        assert!(fs_gate("node-2nd", false).is_ok(), "读照旧");
        assert!(
            fs_gate("node-2nd", true).unwrap_err().contains("观察期"),
            "冷静期内写要被挡"
        );
        assert!(exec_gate("node-2nd").unwrap_err().contains("观察期"));
        // 第一台没有冷静期,照旧全权。
        assert!(fs_gate("node-first", true).is_ok());
        assert!(exec_gate("node-first").is_ok());
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp_db(tag: &str) -> std::sync::MutexGuard<'static, ()> {
        let g = db::TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let p = std::env::temp_dir().join(format!("grants-test-{}-{tag}.db", std::process::id()));
        let _ = std::fs::remove_file(&p);
        std::env::set_var("POLARIS_COLLAB_DB", &p);
        g
    }

    /// 第一台设备免冷静期直接全权;第二台起进冷静期,期间**实际**只给只读。
    #[test]
    fn first_device_is_full_second_is_cooled() {
        let _g = tmp_db("cooldown");
        let (first, fresh) = auto_grant_self("node-a", "acct_1", "我的电脑", true).unwrap();
        assert!(fresh);
        assert!(!first.in_cooldown(), "第一台设备不该有冷静期");
        assert_eq!(first.effective_fs(), FS_RW);
        assert_eq!(first.effective_exec(), EXEC_ALLOW);
        assert!(first.should_mount());

        let (second, _) = auto_grant_self("node-b", "acct_1", "NAS", false).unwrap();
        assert!(second.in_cooldown(), "第二台起必须进冷静期");
        assert_eq!(second.fs_access, FS_RW, "库里记的仍是用户批的档");
        assert_eq!(second.effective_fs(), FS_RO, "但这 24 小时内实际只给只读");
        assert_eq!(second.effective_exec(), EXEC_ASK);
        assert!(second.should_mount(), "只读盘照样该挂上,只是不给写");
    }

    /// 重连不该把用户手工调过的档位冲回默认值 —— 「每次重启权限重置一遍」正是要修的毛病。
    #[test]
    fn reconnect_does_not_reset_user_choice() {
        let _g = tmp_db("keep");
        auto_grant_self("node-a", "acct_1", "NAS", true).unwrap();
        update(
            "node-a",
            None,
            Some(FS_RO),
            Some(EXEC_NONE),
            Some(false),
            "wuli",
        )
        .unwrap();

        let (again, fresh) = auto_grant_self("node-a", "acct_1", "NAS", true).unwrap();
        assert!(!fresh, "已有契约不该被当成新设备");
        assert_eq!(again.fs_access, FS_RO);
        assert_eq!(again.exec_access, EXEC_NONE);
        assert!(!again.auto_mount);
        assert!(!again.should_mount(), "用户关掉自动挂载后就不该再自动挂");
    }

    /// 「信任」按钮:冷静期当场清零,全权立刻生效。
    #[test]
    fn trust_clears_cooldown() {
        let _g = tmp_db("trust");
        auto_grant_self("node-a", "acct_1", "第一台", true).unwrap();
        let (g, _) = auto_grant_self("node-b", "acct_1", "新设备", false).unwrap();
        assert_eq!(g.effective_fs(), FS_RO);

        let g = trust_now("node-b", "wuli").unwrap();
        assert!(!g.in_cooldown());
        assert_eq!(g.effective_fs(), FS_RW);
    }

    /// 撤销 = 入方向直接拒 + 出方向不再挂。没批过的设备不算被撤销(它走别的门)。
    #[test]
    fn revoke_denies_both_directions() {
        let _g = tmp_db("revoke");
        auto_grant_self("node-a", "acct_1", "旧电脑", true).unwrap();
        assert!(!is_revoked("node-a"));

        revoke("node-a", "wuli").unwrap();
        assert!(is_revoked("node-a"));
        let g = get("node-a").unwrap().unwrap();
        assert_eq!(g.effective_fs(), FS_NONE);
        assert_eq!(g.effective_exec(), EXEC_NONE);
        assert!(!g.should_mount());

        // 没批过的设备:不是「被撤销」,别越权把正常首登堵死。
        assert!(!is_revoked("node-never-seen"));
        // 撤销没见过的设备也得成功(丢电脑时用户不该被「它还没登记」挡住)。
        revoke("node-ghost", "wuli").unwrap();
        assert!(is_revoked("node-ghost"));
    }

    #[test]
    fn bad_levels_are_refused() {
        let _g = tmp_db("bad");
        auto_grant_self("node-a", "acct_1", "机器", true).unwrap();
        assert!(update("node-a", None, Some("everything"), None, None, "x").is_err());
        assert!(update("node-a", None, None, Some("root"), None, "x").is_err());
        // 改不存在的设备要报错,不能静默建一条出来。
        assert!(update("node-zzz", None, Some(FS_RO), None, None, "x").is_err());
    }

    #[test]
    fn drive_hint_survives() {
        let _g = tmp_db("drive");
        auto_grant_self("node-a", "acct_1", "NAS", true).unwrap();
        remember_drive("node-a", "Y:").unwrap();
        assert_eq!(get("node-a").unwrap().unwrap().drive_hint, "Y:");
        assert!(any_granted().unwrap());
    }
}
//! collab/identity.rs —— 主机身份、一次性邀请票据、设备白名单。
//!
//! host.key = 主机长期身份密钥（600 权限，永不出主机）。邀请票据 = 一次性配对码，
//! 24h 有效、用后即废。设备白名单 = 隧道层准入键（iroh NodeId），双因子的「设备」那一因子。
use base64::Engine;
use ed25519_dalek::{Signer, SigningKey, VerifyingKey};
use rusqlite::{params, TransactionBehavior};
#[cfg(unix)]
use std::io::Write;
use std::path::PathBuf;

use super::auth;
use super::db::{self, now, open_db};

const TICKET_TTL: i64 = 24 * 3600;

/// host.key 落位：`~/Polaris/data/host.key`，可经 `POLARIS_HOST_KEY` 覆写。
fn host_key_path() -> Option<PathBuf> {
    if let Ok(p) = std::env::var("POLARIS_HOST_KEY") {
        let p = p.trim();
        if !p.is_empty() {
            return Some(PathBuf::from(p));
        }
    }
    directories::UserDirs::new().map(|u| u.home_dir().join("Polaris").join("data").join("host.key"))
}

/// 取（或首次生成）主机身份密钥，返回其 32 字节种子（base64url）。
///
/// 这里用 32 字节随机种子作为主机身份根：iroh 的 SecretKey 也是 32 字节种子，
/// tunnel.rs 上线时直接 `iroh::SecretKey::from_bytes(seed)` 即可，无需二次生成。
pub fn get_or_create_host_key() -> Result<[u8; 32], String> {
    let path = host_key_path().ok_or("无法定位用户目录")?;
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(|e| format!("建数据目录失败: {e}"))?;
    }
    if path.exists() {
        let raw = std::fs::read_to_string(&path).map_err(|e| format!("读 host.key 失败: {e}"))?;
        let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
            .decode(raw.trim())
            .map_err(|e| format!("host.key 损坏: {e}"))?;
        if bytes.len() != 32 {
            return Err("host.key 长度异常".into());
        }
        let mut seed = [0u8; 32];
        seed.copy_from_slice(&bytes);
        return Ok(seed);
    }
    let mut seed = [0u8; 32];
    getrandom::getrandom(&mut seed).map_err(|e| format!("生成密钥失败: {e}"))?;
    let encoded = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(seed);
    // 尽量以 600 权限落盘。
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        let mut f = std::fs::OpenOptions::new()
            .write(true)
            .create(true)
            .truncate(true)
            .mode(0o600)
            .open(&path)
            .map_err(|e| format!("写 host.key 失败: {e}"))?;
        f.write_all(encoded.as_bytes()).map_err(|e| e.to_string())?;
    }
    #[cfg(not(unix))]
    {
        std::fs::write(&path, encoded.as_bytes()).map_err(|e| format!("写 host.key 失败: {e}"))?;
    }
    db::audit("host", "hostkey.create", "", "");
    Ok(seed)
}

/// host.key 的公开指纹（sha256 前 16 字节 hex）——用于成员端固定信任、云机镜像标识。
pub fn host_fingerprint() -> Result<String, String> {
    use sha2::{Digest, Sha256};
    let seed = get_or_create_host_key()?;
    let digest = Sha256::digest(seed);
    Ok(digest[..8].iter().map(|b| format!("{b:02x}")).collect())
}

// ───────────────────────── 设备码连接的 NodeId 持有证明 ─────────────────────────

const CONNECT_PROOF_DOMAIN: &[u8] = b"polaris-collab/connect-pop/v1\0";

/// iroh 1.x 的 EndpointId 展示为 32 字节 Ed25519 公钥 hex。所有设备契约都只存这一种
/// 小写规范形，避免同一把公钥靠大小写变出两行 grant。
pub fn canonical_node_id(raw: &str) -> Result<String, String> {
    let text = raw.trim();
    let bytes = hex::decode(text).map_err(|_| "NodeId 不是有效的 Ed25519 公钥".to_string())?;
    let bytes: [u8; 32] = bytes
        .try_into()
        .map_err(|_| "NodeId 长度异常，应为 32 字节公钥".to_string())?;
    VerifyingKey::from_bytes(&bytes).map_err(|_| "NodeId 不是有效的 Ed25519 公钥".to_string())?;
    Ok(hex::encode(bytes))
}

fn connect_proof_message(node_id: &str, code: &str, challenge: &str) -> Result<Vec<u8>, String> {
    let node_id = canonical_node_id(node_id)?;
    let code = code.trim().to_ascii_uppercase();
    if code.len() != 8 || !code.is_ascii() {
        return Err("设备码格式无效".into());
    }
    let challenge = challenge.trim();
    let challenge_bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(challenge)
        .map_err(|_| "连接挑战格式无效".to_string())?;
    if challenge_bytes.len() != 32 {
        return Err("连接挑战长度异常".into());
    }

    let mut out = Vec::with_capacity(CONNECT_PROOF_DOMAIN.len() + 4 * 3 + 128);
    out.extend_from_slice(CONNECT_PROOF_DOMAIN);
    for field in [challenge.as_bytes(), node_id.as_bytes(), code.as_bytes()] {
        let len = u32::try_from(field.len()).map_err(|_| "连接证明字段过长".to_string())?;
        out.extend_from_slice(&len.to_be_bytes());
        out.extend_from_slice(field);
    }
    Ok(out)
}

/// 用本机 `host.key` 给一次性连接挑战签名。签名前先确认调用方声称的 NodeId 的确由这把
/// 密钥派生；绝不能拿隧道客户端的 `device.key` 代签，它与设备台账里的身份不是一把钥匙。
pub fn sign_connect_proof(node_id: &str, code: &str, challenge: &str) -> Result<String, String> {
    let node_id = canonical_node_id(node_id)?;
    let signing = SigningKey::from_bytes(&get_or_create_host_key()?);
    if hex::encode(signing.verifying_key().to_bytes()) != node_id {
        return Err("本机 NodeId 与 host.key 不匹配，请重启互联服务后重试".into());
    }
    let message = connect_proof_message(&node_id, code, challenge)?;
    Ok(base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(signing.sign(&message).to_bytes()))
}

/// 验证请求者确实持有其所报 NodeId 对应的 host.key。只暴露这个用途固定的验签入口，
/// 不提供“拿主机身份签任意字节”的泛用 API。
pub fn verify_connect_proof(
    node_id: &str,
    code: &str,
    challenge: &str,
    signature: &str,
) -> Result<(), String> {
    let node_id = canonical_node_id(node_id)?;
    let public_bytes: [u8; 32] = hex::decode(&node_id)
        .expect("canonical NodeId is hex")
        .try_into()
        .expect("canonical NodeId is 32 bytes");
    let verifying = VerifyingKey::from_bytes(&public_bytes)
        .map_err(|_| "NodeId 不是有效的 Ed25519 公钥".to_string())?;
    let raw = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(signature.trim())
        .map_err(|_| "连接签名格式无效".to_string())?;
    let signature_bytes: [u8; 64] = raw.try_into().map_err(|_| "连接签名长度异常".to_string())?;
    let signature = ed25519_dalek::Signature::from_bytes(&signature_bytes);
    let message = connect_proof_message(&node_id, code, challenge)?;
    verifying
        .verify_strict(&message, &signature)
        .map_err(|_| "NodeId 持有证明无效".to_string())
}

// ───────────────────────── 设备码(一码) ─────────────────────────
//
// 取代此前的三串码:PLRK1 连接码(裸奔一把 owner 令牌)、PLRS1 分享码、8 位一次性票据。
// 三者的区别全是**我方**的内部概念(谁是主机、谁被邀请、票据烧没烧),对用户毫无意义 ——
// 他心里只有一件事:「把我的码给你,你就能连我」。所以合成一串,而且两边完全对称:
// 每台机器都有自己的码,都能被连,也都能去连别人。「主机」这个词从此不出现在界面上。
//
// 与老连接码的关键差别:码里带的是**访问码**,不是会话令牌。
//  · 老 PLRK1:码 = owner 令牌本身 → 谁拿到谁就是 owner,而且改不了(令牌换了整串码作废,
//    但没有任何 UI 能换它)。
//  · 新设备码:码只是敲门用的口令,由**被连的那台机器**验;验过之后建的是一行
//    `peer_grants` 契约(默认只读),权限由机主在台账上说了算,随时可降可撤。
//    换一串码 = 旧码当场失效 + 靠旧码进来的会话全废。

/// 本机访问码在 meta 里的键。
const ACCESS_CODE_KEY: &str = "device_access_code";

/// 取本机访问码(没有就现生成一串并落库)。
///
/// 这是「一台一串常驻码」的存储层:它跨重启、跨换网、跨换 IP 都不变,
/// 用户复制一次发给谁都行,直到他自己点「换一串」。
pub fn access_code() -> Result<String, String> {
    if let Some(c) = db::meta_get(ACCESS_CODE_KEY) {
        let c = c.trim().to_string();
        if !c.is_empty() {
            return Ok(c);
        }
    }
    let c = random_code();
    db::meta_set(ACCESS_CODE_KEY, &c)?;
    db::audit("system", "devicecode.create", "", "");
    Ok(c)
}

/// 换一串码。旧码当场失效,并把**靠旧码进来的**设备的会话全部作废 ——
/// 「换一串」在用户心里就是「把之前发出去的码全部收回」,只换字符串而不断线是骗人。
///
/// 只清 `granted_by='code'` 那些:同账号自己的设备走的是邮箱登录那条路,与码无关,
/// 不该被换码波及(否则用户换个码,自己的 NAS 盘就掉了)。
pub fn rotate_access_code(actor: &str) -> Result<String, String> {
    let c = random_code();
    let conn = open_db()?;
    // 靠码进来的设备:会话按 device_id(= 对端 NodeId)挂在 sessions 上。
    conn.execute(
        "DELETE FROM sessions WHERE device_id IN \
         (SELECT node_id FROM peer_grants WHERE granted_by=?1)",
        params![super::grants::BY_CODE],
    )
    .map_err(|e| format!("清理旧会话失败: {e}"))?;
    drop(conn);
    db::meta_set(ACCESS_CODE_KEY, &c)?;
    auth::bump_session_revocation();
    db::audit(
        actor,
        "devicecode.rotate",
        "",
        "旧码失效,靠旧码进来的会话已断",
    );
    Ok(c)
}

/// 验一串码。**常量时间**比较:码只有 8 位,逐字节提前返回会把它降成可爆破的长度探测。
pub fn check_access_code(input: &str) -> Result<bool, String> {
    let want = access_code()?;
    let a = want.as_bytes();
    let b = input.trim().to_ascii_uppercase();
    let b = b.as_bytes();
    if a.len() != b.len() {
        return Ok(false);
    }
    let mut diff = 0u8;
    for i in 0..a.len() {
        diff |= a[i] ^ b[i];
    }
    Ok(diff == 0)
}

// ───────────────────────── 邀请票据 ─────────────────────────

#[derive(serde::Serialize)]
pub struct Ticket {
    pub code: String,
    pub role: String,
    pub expires_at: i64,
}

fn random_code() -> String {
    // 人可读配对码：8 位大写字母数字（去掉易混的 0/O/1/I）。
    const ALPH: &[u8] = b"ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
    let mut buf = [0u8; 8];
    getrandom::getrandom(&mut buf).expect("getrandom");
    buf.iter()
        .map(|b| ALPH[(*b as usize) % ALPH.len()] as char)
        .collect()
}

/// 签发一次性邀请票据。role 决定兑换后账号的角色。
pub fn create_ticket(role: &str, note: &str) -> Result<Ticket, String> {
    if !matches!(role, "collaborator" | "visitor") {
        return Err(
            "邀请票据只允许 collaborator 或 visitor；owner 必须通过单独的审计晋升流程授予".into(),
        );
    }
    if note.chars().count() > 200 || note.chars().any(char::is_control) {
        return Err("票据备注最多 200 字且不能包含控制字符".into());
    }
    let conn = open_db()?;
    let code = random_code();
    let t = now();
    conn.execute(
        "INSERT INTO tickets(code,role,created_at,expires_at,note) VALUES(?1,?2,?3,?4,?5)",
        params![code, role, t, t + TICKET_TTL, note],
    )
    .map_err(|e| format!("签发票据失败: {e}"))?;
    db::audit("owner", "ticket.create", role, note);
    Ok(Ticket {
        code,
        role: role.into(),
        expires_at: t + TICKET_TTL,
    })
}

/// 兑换票据 → 建账号 + 登记设备。票据用后即废（幂等：并发下唯一 UPDATE 保证只成一次）。
pub fn redeem_ticket(
    code: &str,
    username: &str,
    password: &str,
    display_name: &str,
    device_name: &str,
    node_id: &str,
) -> Result<(auth::User, String), String> {
    // 先做廉价输入校验并确认票据真实有效，再计算昂贵 Argon2；否则未认证攻击者拿随机
    // 无效码即可让每个请求烧一次密码哈希 CPU。事务内还会再次读取并 CAS，防 TOCTOU。
    auth::validate_new_account_input(username, password, display_name)?;
    let device_name = device_name.trim();
    let node_id = node_id.trim();
    if device_name.is_empty()
        || device_name.chars().count() > 80
        || device_name.chars().any(char::is_control)
    {
        return Err("设备名称长度须为 1–80 个字符且不能包含控制字符".into());
    }
    if node_id.is_empty() || node_id.len() > 256 || node_id.chars().any(char::is_control) {
        return Err("设备标识无效".into());
    }
    {
        let conn = open_db()?;
        let (role, expires_at, used_at) = conn
            .query_row(
                "SELECT role,expires_at,used_at FROM tickets WHERE code=?1",
                params![code.trim()],
                |r| {
                    Ok((
                        r.get::<_, String>(0)?,
                        r.get::<_, i64>(1)?,
                        r.get::<_, Option<i64>>(2)?,
                    ))
                },
            )
            .map_err(|_| "票据无效".to_string())?;
        if used_at.is_some() {
            return Err("票据已被使用".into());
        }
        if expires_at < now() {
            return Err("票据已过期".into());
        }
        if !matches!(role.as_str(), "member" | "collaborator" | "visitor") {
            return Err("该票据角色已停用，请管理员重新签发最小权限票据".into());
        }
    }
    let pass_hash = auth::prepare_new_account(username, password, display_name)?;
    let device_id = random_device_id()?;
    let token = auth::random_token();
    let mut conn = open_db()?;
    let tx = conn
        .transaction_with_behavior(TransactionBehavior::Immediate)
        .map_err(|e| format!("兑换事务失败: {e}"))?;
    let row = tx.query_row(
        "SELECT role,expires_at,used_at FROM tickets WHERE code=?1",
        params![code.trim()],
        |r| {
            Ok((
                r.get::<_, String>(0)?,
                r.get::<_, i64>(1)?,
                r.get::<_, Option<i64>>(2)?,
            ))
        },
    );
    let (mut role, expires_at, used_at) = row.map_err(|_| "票据无效".to_string())?;
    // 兼容旧版 UI 签出的 member 票据；其它高权限旧票据 fail-closed。
    if role == "member" {
        role = "collaborator".into();
    }
    if !matches!(role.as_str(), "collaborator" | "visitor") {
        return Err("该票据角色已停用，请管理员重新签发最小权限票据".into());
    }
    if used_at.is_some() {
        return Err("票据已被使用".into());
    }
    if expires_at < now() {
        return Err("票据已过期".into());
    }
    // 先原子占用票据，防并发重复兑换。used_by 记下兑换账号(管理面可溯源)。
    let claimed = tx
        .execute(
            "UPDATE tickets SET used_at=?1, used_by=?3 WHERE code=?2 AND used_at IS NULL",
            params![now(), code.trim(), username],
        )
        .map_err(|e| e.to_string())?;
    if claimed != 1 {
        return Err("票据已被使用".into());
    }
    let user = auth::insert_user_tx(&tx, username, &pass_hash, &role, display_name)?;
    tx.execute(
        "INSERT INTO devices(id,user_id,name,node_id,added_at) VALUES(?1,?2,?3,?4,?5)",
        params![device_id, user.id, device_name, node_id, now()],
    )
    .map_err(|e| format!("登记设备失败: {e}"))?;
    auth::insert_session_tx(&tx, &token, user.id, node_id)?;
    tx.commit().map_err(|e| format!("提交兑换失败: {e}"))?;
    db::audit(username, "ticket.redeem", code.trim(), &role);
    Ok((user, token))
}

/// 已登录账号凭邀请码入伙:**不建新账号**,只把这台设备绑到当前账号并核销票据。
/// 用户要求的「同账号的人通过邀请码进来」—— 票据上记 used_by=该账号,全程可溯源。
/// 返回设备 id。node_id 已属别的账号会被 ensure_device_for 拒绝(防顶替)。
pub fn redeem_ticket_existing(
    code: &str,
    user: &auth::User,
    device_name: &str,
    node_id: &str,
) -> Result<String, String> {
    let device_name = device_name.trim();
    let node_id = node_id.trim();
    if device_name.is_empty()
        || device_name.chars().count() > 80
        || device_name.chars().any(char::is_control)
    {
        return Err("设备名称长度须为 1–80 个字符且不能包含控制字符".into());
    }
    if node_id.is_empty() || node_id.len() > 256 || node_id.chars().any(char::is_control) {
        return Err("设备标识无效".into());
    }
    let mut conn = open_db()?;
    let tx = conn
        .transaction_with_behavior(TransactionBehavior::Immediate)
        .map_err(|e| format!("兑换事务失败: {e}"))?;
    let (expires_at, used_at) = tx
        .query_row(
            "SELECT expires_at,used_at FROM tickets WHERE code=?1",
            params![code.trim()],
            |r| Ok((r.get::<_, i64>(0)?, r.get::<_, Option<i64>>(1)?)),
        )
        .map_err(|_| "票据无效".to_string())?;
    if used_at.is_some() {
        return Err("票据已被使用".into());
    }
    if expires_at < now() {
        return Err("票据已过期".into());
    }
    // 原子核销 + 记账号(与新建号路径同一并发语义)。
    let claimed = tx
        .execute(
            "UPDATE tickets SET used_at=?1, used_by=?3 WHERE code=?2 AND used_at IS NULL",
            params![now(), code.trim(), user.username],
        )
        .map_err(|e| e.to_string())?;
    if claimed != 1 {
        return Err("票据已被使用".into());
    }
    // 设备绑定(事务内,防并发抢绑同一 node_id)。
    let existing = tx
        .query_row(
            "SELECT id,user_id FROM devices WHERE node_id=?1",
            params![node_id],
            |r| Ok((r.get::<_, String>(0)?, r.get::<_, i64>(1)?)),
        )
        .map(Some)
        .or_else(|e| match e {
            rusqlite::Error::QueryReturnedNoRows => Ok(None),
            other => Err(other.to_string()),
        })?;
    let device_id = match existing {
        Some((_, owner)) if owner != user.id => {
            return Err("该设备已属其他账号,拒绝顶替".into());
        }
        Some((id, _)) => id,
        None => {
            let id = random_device_id()?;
            tx.execute(
                "INSERT INTO devices(id,user_id,name,node_id,added_at) VALUES(?1,?2,?3,?4,?5)",
                params![id, user.id, device_name, node_id, now()],
            )
            .map_err(|e| format!("登记设备失败: {e}"))?;
            id
        }
    };
    tx.commit().map_err(|e| format!("提交兑换失败: {e}"))?;
    db::audit(
        &user.username,
        "ticket.redeem_existing",
        code.trim(),
        device_name,
    );
    Ok(device_id)
}

// ───────────────────────── 分享码(配对码带地址) ─────────────────────────

/// 分享码:`PLRS1-<base64url(json{c:裸码, a:[地址], u:账号中心, k:公钥指纹})>`。
/// 裸码仍单独入库,分享码只是传输壳——成员端解开后逐个探活地址、自动填主机、
/// 再用裸码入伙,零手填。
///
/// `u`/`k` 是联邦模式带的:主机的账号由云端账号中心统管时,收码人得知道
/// **去哪儿登账号**(u)以及**该信任哪把钥匙**(k,人眼核对防中间人)。
/// 本机账号模式下这两项为空,老客户端读不到也不影响(JSON 只加不改)。
pub fn encode_share_code(code: &str, addrs: &[String]) -> String {
    let (authority, kid) = share_authority_hint();
    let mut payload = serde_json::json!({ "c": code, "a": addrs });
    if !authority.is_empty() {
        payload["u"] = serde_json::json!(authority);
        payload["k"] = serde_json::json!(kid);
    }
    let b64 = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(payload.to_string());
    format!("PLRS1-{b64}")
}

/// 本机该往分享码里写哪个账号中心。
///  · 成员主机(delegated)→ 它委托的那个云端账号中心 + 已钉住的公钥指纹。
///  · 权威机自己(authority)→ 就写它自己的对外地址(POLARIS_ADVERTISE_URL)。
///  · 本机账号模式 → 空,分享码里不带这两项。
fn share_authority_hint() -> (String, String) {
    use super::authority::{self, Mode};
    match authority::mode() {
        Mode::Delegated(url) => {
            let kid = authority::pinned().map(|(_, _, k)| k).unwrap_or_default();
            (url, kid)
        }
        Mode::Authority => (
            std::env::var("POLARIS_ADVERTISE_URL").unwrap_or_default(),
            authority::kid().unwrap_or_default(),
        ),
        Mode::Local => (String::new(), String::new()),
    }
}

/// 分享码解出的内容。`authority` 空 = 对方是本机账号模式(老行为)。
pub struct ShareCode {
    pub code: String,
    pub addrs: Vec<String>,
    pub authority: String,
    pub kid: String,
}

/// 分享码 → 结构体。不是分享码/结构不符返回 None(裸码走旧流程)。
pub fn decode_share_code_full(s: &str) -> Option<ShareCode> {
    let b64 = s.trim().strip_prefix("PLRS1-")?;
    let raw = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(b64)
        .ok()?;
    let v: serde_json::Value = serde_json::from_slice(&raw).ok()?;
    Some(ShareCode {
        code: v.get("c")?.as_str()?.to_string(),
        addrs: v
            .get("a")?
            .as_array()?
            .iter()
            .filter_map(|x| x.as_str().map(String::from))
            .collect(),
        authority: v
            .get("u")
            .and_then(|x| x.as_str())
            .unwrap_or_default()
            .to_string(),
        kid: v
            .get("k")
            .and_then(|x| x.as_str())
            .unwrap_or_default()
            .to_string(),
    })
}

/// 分享码 → (裸码, 地址表)。老调用方沿用。
pub fn decode_share_code(s: &str) -> Option<(String, Vec<String>)> {
    decode_share_code_full(s).map(|v| (v.code, v.addrs))
}

// ───────────────────────── 设备白名单 ─────────────────────────

#[derive(serde::Serialize)]
pub struct Device {
    pub id: String,
    pub user_id: i64,
    pub name: String,
    pub node_id: String,
    pub revoked: bool,
}

fn random_device_id() -> Result<String, String> {
    let mut id = [0u8; 12];
    getrandom::getrandom(&mut id).map_err(|e| e.to_string())?;
    Ok(base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(id))
}

/// 登记一台设备到白名单。返回设备 id。
pub fn add_device(user_id: i64, name: &str, node_id: &str) -> Result<String, String> {
    let conn = open_db()?;
    let id = random_device_id()?;
    conn.execute(
        "INSERT INTO devices(id,user_id,name,node_id,added_at) VALUES(?1,?2,?3,?4,?5)",
        params![id, user_id, name, node_id, now()],
    )
    .map_err(|e| format!("登记设备失败: {e}"))?;
    db::audit("owner", "device.add", node_id, name);
    Ok(id)
}

/// 遥测/接入:确保 (user_id, node_id) 有一台设备行,并防顶替。
///  - node_id 已属该用户 → 返回 (id, false=非新建)
///  - node_id 属**别的**用户 → Err(拒绝,阻止成员用别台的 node_id 上报假数据)
///  - node_id 空闲 → 自动登记一台(owner 手机 login/PLRK1 只写 sessions 不写 devices,
///    这里补上设备行,遥测才有卡片承载),返回 (id, true=新建)
pub fn ensure_device_for(
    user_id: i64,
    node_id: &str,
    name: &str,
) -> Result<(String, bool), String> {
    if node_id.trim().is_empty() {
        return Err("node_id 为空".into());
    }
    let conn = open_db()?;
    match conn.query_row(
        "SELECT id,user_id FROM devices WHERE node_id=?1",
        params![node_id],
        |r| Ok((r.get::<_, String>(0)?, r.get::<_, i64>(1)?)),
    ) {
        Ok((id, owner)) => {
            if owner != user_id {
                return Err("该设备已属其他账号,拒绝顶替".into());
            }
            Ok((id, false))
        }
        Err(rusqlite::Error::QueryReturnedNoRows) => {
            let id = random_device_id()?;
            conn.execute(
                "INSERT INTO devices(id,user_id,name,node_id,added_at) VALUES(?1,?2,?3,?4,?5)",
                params![id, user_id, name, node_id, now()],
            )
            .map_err(|e| format!("登记设备失败: {e}"))?;
            Ok((id, true))
        }
        Err(e) => Err(e.to_string()),
    }
}

/// 吊销设备并删除它的全部 HTTP/WS 会话。已建立的长连接会在断开/重连时失效；
/// 真正“即时踢线”还需要连接注册表主动 close，不能在 UI 中宣称已经完成。
/// 返回该设备的 node_id —— 调用方据此同步踢掉云机中继上的挂牌(gateway::unregister_node)。
pub fn revoke_device(device_id: &str) -> Result<String, String> {
    let mut conn = open_db()?;
    let tx = conn
        .transaction_with_behavior(TransactionBehavior::Immediate)
        .map_err(|e| format!("吊销事务失败: {e}"))?;
    let node_id: String = tx
        .query_row(
            "SELECT node_id FROM devices WHERE id=?1",
            params![device_id],
            |r| r.get(0),
        )
        .map_err(|_| "设备不存在".to_string())?;
    tx.execute(
        "UPDATE devices SET revoked=1 WHERE id=?1",
        params![device_id],
    )
    .map_err(|e| e.to_string())?;
    tx.execute("DELETE FROM sessions WHERE device_id=?1", params![node_id])
        .map_err(|e| e.to_string())?;
    tx.commit().map_err(|e| format!("提交吊销失败: {e}"))?;
    // 会话短缓存立即失效:否则被吊销设备的 token 还能在缓存 TTL(10s)内继续鉴权通过。
    super::auth::bump_session_revocation();
    db::audit("owner", "device.revoke", device_id, &node_id);
    Ok(node_id)
}

/// 某 NodeId 是否在白名单内且未吊销 —— tunnel.rs 准入判定的确定性入口。
pub fn is_node_allowed(node_id: &str) -> bool {
    match open_db() {
        Ok(conn) => conn
            .query_row(
                "SELECT COUNT(*) FROM devices WHERE node_id=?1 AND revoked=0",
                params![node_id],
                |r| r.get::<_, i64>(0),
            )
            .map(|n| n > 0)
            .unwrap_or(false),
        Err(_) => false,
    }
}

/// 列白名单设备（owner 管理面）。
pub fn list_devices() -> Result<Vec<Device>, String> {
    let conn = open_db()?;
    let mut stmt = conn
        .prepare("SELECT id,user_id,name,node_id,revoked FROM devices ORDER BY added_at DESC")
        .map_err(|e| e.to_string())?;
    let rows = stmt
        .query_map([], |r| {
            Ok(Device {
                id: r.get(0)?,
                user_id: r.get(1)?,
                name: r.get(2)?,
                node_id: r.get(3)?,
                revoked: r.get::<_, i64>(4)? != 0,
            })
        })
        .map_err(|e| e.to_string())?;
    rows.collect::<Result<_, _>>().map_err(|e| e.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn with_tmp_db() -> (std::sync::MutexGuard<'static, ()>, PathBuf) {
        let guard = crate::collab::db::TEST_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let path = std::env::temp_dir().join(format!(
            "collab-identity-{}-{}.db",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::env::set_var("POLARIS_COLLAB_DB", &path);
        (guard, path)
    }

    #[test]
    fn connect_proof_roundtrip_and_field_binding() {
        let signing = SigningKey::from_bytes(&[7u8; 32]);
        let node_id = hex::encode(signing.verifying_key().to_bytes());
        let challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode([9u8; 32]);
        let message = connect_proof_message(&node_id, "ABCD2345", &challenge).unwrap();
        let signature = base64::engine::general_purpose::URL_SAFE_NO_PAD
            .encode(signing.sign(&message).to_bytes());

        verify_connect_proof(&node_id, "ABCD2345", &challenge, &signature).unwrap();
        assert!(verify_connect_proof(&node_id, "ABCD2346", &challenge, &signature).is_err());
        let other_challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode([10u8; 32]);
        assert!(verify_connect_proof(&node_id, "ABCD2345", &other_challenge, &signature).is_err());
    }

    #[test]
    fn connect_proof_cannot_claim_another_node_id() {
        let claimed = SigningKey::from_bytes(&[1u8; 32]);
        let attacker = SigningKey::from_bytes(&[2u8; 32]);
        let node_id = hex::encode(claimed.verifying_key().to_bytes());
        let challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode([3u8; 32]);
        let message = connect_proof_message(&node_id, "ABCD2345", &challenge).unwrap();
        let forged = base64::engine::general_purpose::URL_SAFE_NO_PAD
            .encode(attacker.sign(&message).to_bytes());

        assert!(verify_connect_proof(&node_id, "ABCD2345", &challenge, &forged).is_err());
    }

    #[test]
    fn connect_proof_rejects_malformed_inputs_and_canonicalizes_node_id() {
        let signing = SigningKey::from_bytes(&[4u8; 32]);
        let node_id = hex::encode(signing.verifying_key().to_bytes());
        assert_eq!(
            canonical_node_id(&node_id.to_ascii_uppercase()).unwrap(),
            node_id
        );
        assert!(canonical_node_id("not-a-node").is_err());
        assert!(canonical_node_id(&"00".repeat(31)).is_err());

        let challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode([5u8; 32]);
        assert!(verify_connect_proof(&node_id, "ABCD2345", &challenge, "not-base64!").is_err());
        let short_signature = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode([0u8; 63]);
        assert!(verify_connect_proof(&node_id, "ABCD2345", &challenge, &short_signature).is_err());
        let short_challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode([0u8; 31]);
        assert!(connect_proof_message(&node_id, "ABCD2345", &short_challenge).is_err());
    }

    #[test]
    fn share_code_roundtrip() {
        let addrs = vec![
            "http://192.168.1.5:8484".to_string(),
            "http://100.1.2.3:8484".to_string(),
        ];
        let s = encode_share_code("ABCD2345", &addrs);
        assert!(s.starts_with("PLRS1-"));
        let (code, back) = decode_share_code(&s).unwrap();
        assert_eq!(code, "ABCD2345");
        assert_eq!(back, addrs);
    }

    #[test]
    fn share_code_rejects_garbage() {
        assert!(decode_share_code("ABCD2345").is_none()); // 裸码不是分享码
        assert!(decode_share_code("PLRS1-!!!not-b64").is_none()); // 坏 base64
        assert!(decode_share_code("PLRS1-e30").is_none()); // 合法 b64 但缺字段({})
    }

    #[test]
    fn invalid_signup_does_not_consume_ticket() {
        let (_guard, path) = with_tmp_db();
        let ticket = create_ticket("collaborator", "atomic").unwrap();
        assert!(redeem_ticket(
            &ticket.code,
            "alice",
            "short",
            "Alice",
            "Alice laptop",
            "node-alice",
        )
        .is_err());
        let (user, token) = redeem_ticket(
            &ticket.code,
            "alice",
            "correct-horse",
            "Alice",
            "Alice laptop",
            "node-alice",
        )
        .unwrap();
        assert_eq!(user.role, "collaborator");
        assert!(!token.is_empty());
        assert!(redeem_ticket(
            &ticket.code,
            "alice2",
            "correct-horse",
            "Alice 2",
            "another laptop",
            "node-alice-2",
        )
        .is_err());
        std::env::remove_var("POLARIS_COLLAB_DB");
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn redeem_existing_binds_device_and_records_account() {
        let (_guard, path) = with_tmp_db();
        let alice =
            crate::collab::auth::create_user("alice", "correct-horse", "owner", "Alice").unwrap();
        let bob = crate::collab::auth::create_user("bob", "correct-horse", "collaborator", "Bob")
            .unwrap();
        // 已登录账号凭码入伙:不建新号,设备绑到 alice,票据核销并记 used_by。
        let t = create_ticket("collaborator", "for-alice-laptop").unwrap();
        let dev = redeem_ticket_existing(&t.code, &alice, "Alice 二号机", "node-alice-2").unwrap();
        assert!(!dev.is_empty());
        let conn = open_db().unwrap();
        let used_by: String = conn
            .query_row(
                "SELECT used_by FROM tickets WHERE code=?1",
                params![t.code],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(used_by, "alice");
        // 票据用后即废:同码再兑失败。
        assert!(redeem_ticket_existing(&t.code, &alice, "又一台", "node-x").is_err());
        // 防顶替:bob 拿新票据也不能绑走 alice 的 node_id。
        let t2 = create_ticket("collaborator", "bob-tries").unwrap();
        assert!(redeem_ticket_existing(&t2.code, &bob, "Bob 机", "node-alice-2").is_err());
        std::env::remove_var("POLARIS_COLLAB_DB");
        let _ = std::fs::remove_file(path);
    }

    /// 设备码:一台一串、常驻不变、大小写不敏感。
    #[test]
    fn device_code_is_stable_and_case_insensitive() {
        let (_guard, _path) = with_tmp_db();
        let a = access_code().unwrap();
        assert_eq!(a.chars().count(), 8);
        assert_eq!(access_code().unwrap(), a, "常驻码不能每次调用都变一串");
        assert!(check_access_code(&a).unwrap());
        assert!(
            check_access_code(&a.to_ascii_lowercase()).unwrap(),
            "手打小写也得认"
        );
        assert!(
            check_access_code(&format!("  {a}  ")).unwrap(),
            "粘贴带空格也得认"
        );
        assert!(!check_access_code("ZZZZZZZZ").unwrap());
        assert!(!check_access_code("").unwrap());
        assert!(!check_access_code(&a[..7]).unwrap(), "长度不对必须拒");
    }

    /// 「换一串」= 旧码当场失效 **且** 靠旧码进来的会话断掉。
    /// 只换字符串而不断线是骗人 —— 用户点它的本意就是「把发出去的码全收回」。
    #[test]
    fn rotate_kills_the_old_code_and_its_sessions() {
        let (_guard, _path) = with_tmp_db();
        let old = access_code().unwrap();
        // 一台靠码进来的设备 + 它的会话。
        super::super::grants::grant_by_code("node-guest", "访客机").unwrap();
        // 机主后来点过「信任这台」也仍然是「靠码进来的」；信任只升权限，不能抹掉来源。
        let trusted = super::super::grants::trust_fully("node-guest", "本机").unwrap();
        assert_eq!(trusted.granted_by, super::super::grants::BY_CODE);
        let guest = auth::peer_guest_user().unwrap();
        let tok = auth::issue_session(guest.id, "node-guest").unwrap();
        assert!(auth::check_session(&tok).is_ok());
        // 同账号自己的设备(走邮箱登录那条路)不该被换码波及。
        super::super::grants::auto_grant_self("node-mine", "acct_1", "我的 NAS", true).unwrap();
        let mine = auth::issue_session(guest.id, "node-mine").unwrap();

        let new = rotate_access_code("本机").unwrap();
        assert_ne!(new, old);
        assert!(!check_access_code(&old).unwrap(), "旧码必须当场失效");
        assert!(check_access_code(&new).unwrap());
        assert!(auth::check_session(&tok).is_err(), "靠旧码进来的会话必须断");
        assert!(
            auth::check_session(&mine).is_ok(),
            "自己的设备走的是另一条路,换码不该把它的盘弄掉线"
        );
    }

    #[test]
    fn tickets_cannot_grant_owner() {
        let (_guard, path) = with_tmp_db();
        assert!(create_ticket("owner", "too much privilege").is_err());
        std::env::remove_var("POLARIS_COLLAB_DB");
        let _ = std::fs::remove_file(path);
    }
}

//! mesh.rs —— 同账号设备网的**客户端**(Tailscale 式「登录即成网」)。
//!
//! 在此之前,接入一台自己的远程主机要手工粘一串 PLRK1 连接码;N 台机器两两互连是 N² 次
//! 粘贴,还要各自保管对端的 owner 令牌。这个模块把那一步整个删掉:
//!
//! ```text
//! 用户在统一登录页填「邮箱 + 验证码」
//!   → 本机拿到身份断言 → pin 账号中心并通过本机成员准入
//!   → 向云端目录入网,把长期设备密钥 + UID + URL 原子落入 collab.db
//!   → 后台每 60s:报到 + 取同账号设备清单
//!       对清单里的设备实探 tunnel/session:
//!         iroh 隧道 → 拿新断言去**对端**换它的本机会话 token → fs_mount 挂成本机盘符
//! ```
//!
//! 三条设计上的要紧事:
//!  · **云端不持有远程盘会话或设备私钥。** 它只签身份断言；对端还要经过自己的成员资格、
//!    设备 proof、grant/冷静期与撤销闸。账号中心签名权一旦失陷仍是严重事件（可伪造身份），
//!    因而公网传输必须 HTTPS、authority 必须 pin，不能把“云端不存盘 token”夸成绝对安全。
//!  · **设备密钥落本机、可按设备吊销。** 丢一台电脑不必改密码,在别的设备上把它踢出设备网即可。
//!  · **对端离线不拆盘。** 只要它还在设备网名册上,盘符就留着,由 fsmount 看门狗等它回来 ——
//!    拆了再挂会换盘符,正在用的资源管理器窗口全断,那比"暂时读不到"糟得多。
#![cfg(feature = "collab-host")]

use serde_json::{json, Value};
use std::collections::HashMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Mutex, OnceLock};
use std::time::Duration;

/// 心跳周期。权威侧判在线的窗口是它的 3 倍余量(见 collab::mesh::ONLINE_WINDOW)。
const ANNOUNCE_TICK: Duration = Duration::from_secs(60);
/// 首次入网后第一轮对账等多久 —— 别让用户填完账号还要干等一分钟。
const FIRST_TICK: Duration = Duration::from_secs(2);
/// 设备网专用的本地隧道端口起点。手工添加的远程源用 18620+,这里另起一段不打架。
const PORT_BASE: u16 = 18800;
/// 与云端账号中心通信的超时。连不上要快失败:后台循环下一拍再试,不能把线程吊死。
const CLOUD_TIMEOUT: Duration = Duration::from_secs(12);

/// 默认账号中心仍是现有云机。它目前只有 HTTP，因而新登录不会静默使用：UI 会展开
/// 高级设置并要求用户显式确认明文风险；自建部署应通过环境变量或表单提供真实 HTTPS 地址。
const DEFAULT_AUTHORITY: &str = "http://43.139.209.127:8080";

/// 入网地址:用户填了就用用户的;没填先看环境变量(server 形态),最后落到官方云机。
fn default_authority() -> String {
    std::env::var("POLARIS_ACCOUNT_AUTHORITY_URL")
        .ok()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| DEFAULT_AUTHORITY.to_string())
}

// meta 键(都落在 collab.db,桌面双击启动也能读到 —— 环境变量在这个场景根本不存在)
const K_URL: &str = "mesh_url";
const K_KEY: &str = "mesh_key";
const K_UID: &str = "mesh_uid";

// ────────────────────────────── 本机身份小工具 ──────────────────────────────

fn my_name() -> String {
    std::env::var("COMPUTERNAME")
        .or_else(|_| std::env::var("HOSTNAME"))
        .unwrap_or_else(|_| "我的电脑".into())
}

fn my_os() -> String {
    std::env::consts::OS.to_string()
}

fn my_ver() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

/// 本机 iroh NodeId。设备网里「一台机器」的身份就是它。
/// 还没就绪(隧道未起/无 collab-net)时返回空串 —— 调用方据此判「稍后重试」。
fn my_node_id() -> String {
    #[cfg(feature = "collab-net")]
    {
        crate::collab::tunnel::host_node_id().unwrap_or_default()
    }
    #[cfg(not(feature = "collab-net"))]
    {
        String::new()
    }
}

// ────────────────────────────── 落库的入网状态 ──────────────────────────────

fn meta(k: &str) -> String {
    crate::collab::db::meta_get(k).unwrap_or_default()
}

/// 账号 UID 只有在设备密钥仍有效时才是当前身份。旧版本退网只清 `mesh_key`，因此这里也
/// fail closed：哪怕磁盘里残留过 UID，未入网状态也绝不再把它当成当前账号回给 UI。
fn current_uid(enrolled: bool, stored: String) -> String {
    if enrolled {
        stored
    } else {
        String::new()
    }
}

fn visible_uid() -> String {
    current_uid(cfg().is_some(), meta(K_UID))
}

struct Cfg {
    url: String,
    key: String,
}

/// 已入网的配置。任一项为空 = 还没入网。
fn cfg() -> Option<Cfg> {
    let url = meta(K_URL);
    let key = meta(K_KEY);
    if url.is_empty() || key.is_empty() {
        return None;
    }
    Some(Cfg { url, key })
}

// ────────────────────────────── 已建立的链路 ──────────────────────────────

struct Link {
    name: String,
    port: u16,
    /// 对端主机签给我的会话 token;None = 还没换到(下一拍重试)。
    token: Option<String>,
    /// 当前链路阶段：connecting / authenticating / mounting / ready / degraded。
    phase: String,
    /// 稳定错误码，UI 不再靠中文文案猜故障类型。
    error_code: String,
    /// 最近一次 tunnel + token 探测同时通过的 unix 秒。
    last_verified_at: u64,
    /// 最近一次失败原因(UI 如实展示,不糊成「连接中」)。
    err: String,
}

fn now_secs() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn link_connected(link: &Link) -> bool {
    let recently_verified = link.token.is_some()
        && link.last_verified_at > 0
        && now_secs().saturating_sub(link.last_verified_at) <= 180;
    #[cfg(feature = "collab-net")]
    {
        recently_verified && crate::collab::tunnel::client_state(link.port).connected
    }
    #[cfg(not(feature = "collab-net"))]
    {
        let _ = recently_verified;
        false
    }
}

fn links() -> &'static Mutex<HashMap<String, Link>> {
    static L: OnceLock<Mutex<HashMap<String, Link>>> = OnceLock::new();
    L.get_or_init(|| Mutex::new(HashMap::new()))
}

fn source_id(node_id: &str) -> String {
    format!("mesh-{}", &node_id[..node_id.len().min(16)])
}

/// 给一台新设备分一个本地端口。已在册的沿用原端口(重试不换口,免得旧隧道占着不放)。
fn port_for(node_id: &str) -> u16 {
    let map = links().lock().unwrap();
    if let Some(l) = map.get(node_id) {
        return l.port;
    }
    let used: Vec<u16> = map.values().map(|l| l.port).collect();
    let mut p = PORT_BASE;
    while used.contains(&p) {
        p += 1;
    }
    p
}

// ────────────────────────────── 与云端目录通信 ──────────────────────────────

fn agent() -> ureq::Agent {
    ureq::AgentBuilder::new()
        .timeout_connect(CLOUD_TIMEOUT)
        .timeout_read(CLOUD_TIMEOUT)
        .build()
}

/// 把 ureq 错误翻成人话。云端明确给的业务错误原样透传(「设备已被移出设备网」这类
/// 必须让用户看见原文,糊成「网络错误」会让人对着正确的账号反复试)。
fn cloud_err(e: ureq::Error) -> String {
    match e {
        ureq::Error::Status(code, resp) => {
            let body = resp.into_string().unwrap_or_default();
            serde_json::from_str::<Value>(&body)
                .ok()
                .and_then(|v| v.get("error").and_then(|x| x.as_str()).map(String::from))
                .unwrap_or_else(|| format!("HTTP {code}"))
        }
        ureq::Error::Transport(t) => format!("连不上云端账号中心:{t}"),
    }
}

fn norm_url(u: &str) -> String {
    let t = u.trim().trim_end_matches('/');
    if t.starts_with("http://") || t.starts_with("https://") {
        t.to_string()
    } else {
        format!("https://{t}")
    }
}

fn loopback_http(url: &str) -> bool {
    let Some(rest) = url.strip_prefix("http://") else {
        return false;
    };
    let authority = rest.split('/').next().unwrap_or("");
    let host = authority.rsplit('@').next().unwrap_or(authority);
    host == "localhost"
        || host.starts_with("localhost:")
        || host == "127.0.0.1"
        || host.starts_with("127.0.0.1:")
        || host == "[::1]"
        || host.starts_with("[::1]:")
}

/// 登录凭据、OTP、assertion 与长期 meshKey 都会经过账号中心。公网 HTTP 必须显式确认，
/// 不能再因为用户把“高级地址”留空，就静默把整套身份发到明文 IP。
fn validate_authority_url(raw: &str, allow_insecure_http: bool) -> Result<String, String> {
    let url = norm_url(raw);
    if url == "https://" || url == "http://" {
        return Err("请填写账号中心地址".into());
    }
    if url.starts_with("https://") || loopback_http(&url) {
        return Ok(url);
    }
    if url.starts_with("http://") {
        if allow_insecure_http {
            return Ok(url);
        }
        return Err(format!(
            "账号中心 {url} 使用明文 HTTP，邮箱、验证码和设备密钥可能被窃取。请改用 HTTPS；若这是你明确信任的旧服务，请在高级设置勾选‘仍使用不安全 HTTP’后重试"
        ));
    }
    Err("账号中心地址只支持 https://（本机调试可用 http://localhost）".into())
}

fn authority_transport_state(url: &str) -> &'static str {
    if url.starts_with("https://") || loopback_http(url) {
        "secure"
    } else {
        "insecure_legacy"
    }
}

/// 心跳 + 取同账号设备清单。
fn announce(c: &Cfg) -> Result<Vec<Value>, String> {
    let resp = agent()
        .post(&format!("{}/api/mesh/announce", c.url))
        .set("Authorization", &format!("Bearer {}", c.key))
        .send_json(json!({ "name": my_name(), "os": my_os(), "ver": my_ver() }))
        .map_err(cloud_err)?;
    let v: Value = resp
        .into_json()
        .map_err(|e| format!("云端返回的不是 JSON:{e}"))?;
    if let Some(uid) = v.get("uid").and_then(|x| x.as_str()) {
        let _ = crate::collab::db::meta_set(K_UID, uid);
    }
    Ok(v.get("peers")
        .and_then(|x| x.as_array())
        .cloned()
        .unwrap_or_default())
}

/// 取一张新的身份断言(5 分钟有效),用来进对端主机的门。
fn fresh_assertion(c: &Cfg) -> Result<String, String> {
    let resp = agent()
        .post(&format!("{}/api/mesh/assert", c.url))
        .set("Authorization", &format!("Bearer {}", c.key))
        .send_json(json!({}))
        .map_err(cloud_err)?;
    let v: Value = resp
        .into_json()
        .map_err(|e| format!("云端返回的不是 JSON:{e}"))?;
    v.get("assertion")
        .and_then(|x| x.as_str())
        .map(String::from)
        .ok_or_else(|| "云端没返回身份断言".into())
}

/// 拿断言去**对端**(经隧道的本地口)换它的本机会话 token。
///
/// 这一步会失败的正常情形:对端还没把我这个账号加成它的成员。此时报错原文就是对端给的
/// 「本主机还没有邀请你」—— 如实展示给用户,他知道该去那台机器上放行。
fn login_peer(port: u16, assertion: &str) -> Result<String, String> {
    let resp = agent()
        .post(&format!(
            "http://127.0.0.1:{port}/api/collab/login_assertion"
        ))
        .send_json(json!({ "assertion": assertion, "deviceId": my_node_id() }))
        .map_err(cloud_err)?;
    let v: Value = resp
        .into_json()
        .map_err(|e| format!("对端返回的不是 JSON:{e}"))?;
    v.get("token")
        .and_then(|x| x.as_str())
        .map(String::from)
        .ok_or_else(|| "对端没返回会话 token".into())
}

/// 同时验证 loopback 隧道与对端 session。`token.is_some()` 只能说明过去登录成功过，
/// 不能证明 tunnel 仍 connected、session 没被撤销；用轻量 `/api/collab/me` 才是事实。
fn probe_peer_session(port: u16, token: &str) -> Result<(), String> {
    agent()
        .get(&format!("http://127.0.0.1:{port}/api/collab/me"))
        .set("Authorization", &format!("Bearer {token}"))
        .call()
        .map(|_| ())
        .map_err(cloud_err)
}

// ────────────────────────────── 对账:清单 → 隧道 + 盘符 ──────────────────────────────

/// 确保一台设备的 tunnel、session 与挂载凭据都真实可用；历史 token 只是一条缓存，
/// 每轮对账都要用 tunnel registry + `/api/collab/me` 重新证明，不能拿缓存冒充在线。
async fn ensure_peer(c: &Cfg, node_id: &str, name: &str, uid: &str) {
    // 首次见到这台同账号设备 → 自动批准(带冷静期);已有契约 = 原样沿用用户调过的档。
    let first = !crate::collab::grants::any_granted().unwrap_or(false);
    let grant = match crate::collab::grants::auto_grant_self(node_id, uid, name, first) {
        Ok((g, _)) => g,
        Err(e) => {
            set_err(node_id, "grant_failed", format!("登记设备契约失败:{e}"));
            return;
        }
    };
    if grant.revoked || !grant.should_mount() {
        // 授权降为不可挂载时要立刻收回已经存在的盘和隧道，不能只阻止下一次新建。
        drop_peer(node_id).await;
        return;
    }
    let ro = grant.effective_fs() == crate::collab::grants::FS_RO;
    let drive_hint = grant.drive_hint.clone();
    let port = port_for(node_id);
    {
        let mut map = links().lock().unwrap();
        let link = map.entry(node_id.to_string()).or_insert_with(|| Link {
            name: name.to_string(),
            port,
            token: None,
            phase: "connecting".into(),
            error_code: String::new(),
            last_verified_at: 0,
            err: String::new(),
        });
        link.name = name.to_string();
    }

    // 快路径也必须实探。会话仍有效且 mount 已登记时，仅原位刷新 token，盘符完全不动。
    let cached = links()
        .lock()
        .unwrap()
        .get(node_id)
        .and_then(|l| l.token.clone());
    if let Some(token) = cached {
        #[cfg(feature = "collab-net")]
        let tunnel_ok = crate::collab::tunnel::client_state(port).connected;
        #[cfg(not(feature = "collab-net"))]
        let tunnel_ok = false;
        if tunnel_ok {
            let probe_token = token.clone();
            let probe = tokio::task::spawn_blocking(move || probe_peer_session(port, &probe_token))
                .await
                .unwrap_or_else(|e| Err(format!("探活任务失败:{e}")));
            if probe.is_ok() {
                let sid = source_id(node_id);
                if crate::fsmount::fs_mount_refresh_token(&sid, &token) {
                    let mounted = crate::fsmount::fs_mount_status()
                        .into_iter()
                        .find(|v| v.get("sourceId").and_then(|x| x.as_str()) == Some(sid.as_str()));
                    let mount_ok = mounted
                        .as_ref()
                        .and_then(|v| v.get("ok"))
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false);
                    mark_verified(node_id, if mount_ok { "ready" } else { "mounting" });
                    return;
                }
                // session/tunnel 健康但挂载记录丢了：直接复用已经实探通过的 session。
                // 账号中心临时离线不应阻止一块仍获授权的远程盘恢复。
                match crate::fsmount::fs_mount(
                    sid,
                    name.to_string(),
                    node_id.to_string(),
                    port,
                    token.clone(),
                    Some(ro),
                    Some(drive_hint.clone()),
                )
                .await
                {
                    Ok(v) => {
                        let mount_ok = v.get("ok").and_then(|x| x.as_bool()).unwrap_or(false);
                        mark_verified(node_id, if mount_ok { "ready" } else { "mounting" });
                        if let Some(d) = v["drive"].as_str().filter(|s| !s.is_empty()) {
                            let _ = crate::collab::grants::remember_drive(node_id, d);
                        }
                    }
                    Err(e) => set_err(node_id, "mount_failed", format!("挂盘失败:{e}")),
                }
                return;
            } else if let Err(e) = probe {
                set_err(node_id, "session_probe_failed", e);
            }
        } else {
            let detail = {
                #[cfg(feature = "collab-net")]
                {
                    let s = crate::collab::tunnel::client_state(port);
                    if s.last_error.is_empty() {
                        format!("隧道状态:{}", s.state)
                    } else {
                        s.last_error
                    }
                }
                #[cfg(not(feature = "collab-net"))]
                {
                    "此构建没有 P2P 隧道(collab-net)".to_string()
                }
            };
            set_err(node_id, "tunnel_unhealthy", detail);
        }
        if let Some(l) = links().lock().unwrap().get_mut(node_id) {
            l.token = None;
        }
    }

    set_phase(node_id, "connecting");
    #[cfg(feature = "collab-net")]
    {
        let nid = node_id.to_string();
        let r =
            tokio::task::spawn_blocking(move || crate::collab::tunnel::connect_client(&nid, port))
                .await;
        match r {
            Ok(Ok(())) => {}
            Ok(Err(e)) => {
                set_err(
                    node_id,
                    "tunnel_connect_failed",
                    format!("隧道建立失败:{e}"),
                );
                return;
            }
            Err(e) => {
                set_err(node_id, "tunnel_task_failed", format!("隧道任务失败:{e}"));
                return;
            }
        }
    }
    #[cfg(not(feature = "collab-net"))]
    {
        set_err(
            node_id,
            "collab_net_missing",
            "此构建没有 P2P 隧道(collab-net),设备网只能看不能连".into(),
        );
        return;
    }

    set_phase(node_id, "authenticating");
    let url = c.url.clone();
    let key = c.key.clone();
    let got = tokio::task::spawn_blocking(move || {
        let a = fresh_assertion(&Cfg { url, key })?;
        login_peer(port, &a)
    })
    .await
    .unwrap_or_else(|e| Err(format!("登录任务失败:{e}")));
    let token = match got {
        Ok(t) => t,
        Err(e) => {
            set_err(node_id, "peer_login_failed", e);
            return;
        }
    };

    set_phase(node_id, "mounting");
    let sid = source_id(node_id);
    if crate::fsmount::fs_mount_refresh_token(&sid, &token) {
        if let Some(l) = links().lock().unwrap().get_mut(node_id) {
            l.token = Some(token);
        }
        mark_verified(node_id, "mounting");
        return;
    }
    match crate::fsmount::fs_mount(
        sid,
        name.to_string(),
        node_id.to_string(),
        port,
        token.clone(),
        Some(ro),
        Some(drive_hint),
    )
    .await
    {
        Ok(v) => {
            if let Some(l) = links().lock().unwrap().get_mut(node_id) {
                l.token = Some(token);
            }
            let mount_ok = v.get("ok").and_then(|x| x.as_bool()).unwrap_or(false);
            mark_verified(node_id, if mount_ok { "ready" } else { "mounting" });
            if let Some(d) = v["drive"].as_str().filter(|s| !s.is_empty()) {
                let _ = crate::collab::grants::remember_drive(node_id, d);
            }
            eprintln!(
                "[mesh] 「{name}」已接入(端口 {port},盘:{}{})",
                v["drive"],
                if ro { ",只读" } else { "" }
            );
        }
        Err(e) => set_err(node_id, "mount_failed", format!("挂盘失败:{e}")),
    }
}

fn set_phase(node_id: &str, phase: &str) {
    if let Some(l) = links().lock().unwrap().get_mut(node_id) {
        l.phase = phase.to_string();
    }
}

fn mark_verified(node_id: &str, phase: &str) {
    if let Some(l) = links().lock().unwrap().get_mut(node_id) {
        l.phase = phase.to_string();
        l.error_code.clear();
        l.err.clear();
        l.last_verified_at = now_secs();
    }
}

fn set_err(node_id: &str, code: &str, e: String) {
    eprintln!("[mesh] {node_id} 接入未成({code}):{e}");
    let mut map = links().lock().unwrap();
    if let Some(l) = map.get_mut(node_id) {
        l.phase = "degraded".into();
        l.error_code = code.to_string();
        l.err = e;
    }
}

/// 从设备网名册里消失的设备(被吊销/被踢):拆盘 + 断隧道。
/// **只在"名册里没了"时拆** —— 单纯离线不拆(见文件头第三条)。
async fn drop_peer(node_id: &str) {
    let l = links().lock().unwrap().remove(node_id);
    // 挂载注册表和链路表应当同生共死，但撤权路径必须以“收回能力”为准：即使某次
    // 异常只留下了挂载，也照样幂等卸掉，不能因链路记录缺失而提前返回。
    let _ = crate::fsmount::fs_unmount(source_id(node_id)).await;
    let Some(l) = l else { return };
    #[cfg(feature = "collab-net")]
    {
        let port = l.port;
        let _ = tokio::task::spawn_blocking(move || crate::collab::tunnel::disconnect_client(port))
            .await;
    }
    eprintln!("[mesh] 「{}」已移出设备网,盘符已收回", l.name);
}

/// 本机成员资格的**旧状态自愈**：历史版本可能已先保存 meshKey，却没能进自己这台机器的门。
///
/// 新登录现在会在云端 enroll 前完成本机准入，不再产生这种半成品；这里仍要照顾磁盘上已经
/// 存在的旧状态，否则升级后登录卡不会再出现，而设备之间仍会因为缺少本机成员资格互相挡回去。
///
/// 便宜：先纯本地读一次成员资格（命中即 no-op，这是绝大多数情况），真的缺才去取一张断言。
/// 用的是本机自己的设备密钥 + [`login_with_assertion_local`]，与用户在这台机器前亲手登录同权。
fn heal_local_membership(c: &Cfg) {
    let uid = meta(K_UID);
    if uid.is_empty() || crate::collab::authority::is_member(&uid) {
        return;
    }
    let node_id = my_node_id();
    if node_id.is_empty() {
        return;
    }
    let r = fresh_assertion(c)
        .and_then(|a| crate::collab::authority::login_with_assertion_local(&a, &node_id));
    match r {
        Ok((u, _)) => {
            eprintln!("[mesh] 本机成员资格已补上(角色 {})", u.role);
            member_warn().lock().unwrap().clear();
        }
        // 补不上是有正当理由的(这台机器的主人是别人 → 要邀请码)。如实记下来给 UI 展示,
        // 但只在原因变了的时候刷屏,别每 60 秒吼一遍同一句话。
        Err(e) => {
            let mut w = member_warn().lock().unwrap();
            if *w != e {
                eprintln!("[mesh] 本机还不认这个账号:{e}");
                *w = e;
            }
        }
    }
}

/// 最近一次「进不了本机的门」的原因。空 = 没问题。UI 拿它提示用户去要一张邀请码。
fn member_warn() -> &'static Mutex<String> {
    static W: OnceLock<Mutex<String>> = OnceLock::new();
    W.get_or_init(|| Mutex::new(String::new()))
}

/// enrollment 的“有密钥”和“能双向互联”是两回事。旧版本可能已经留下 meshKey，
/// 却没有正确 pin authority 或本机成员资格；这里每次从真实持久状态推导，不相信旧成功标志。
fn enrollment_state() -> (String, bool, bool, String) {
    let Some(c) = cfg() else {
        return ("logged_out".into(), false, false, "本机还没登录".into());
    };
    let secure = authority_transport_state(&c.url) == "secure";
    let pinned = crate::collab::authority::pinned()
        .is_some_and(|(url, _, _)| url.trim_end_matches('/') == c.url.trim_end_matches('/'));
    if !pinned {
        return (
            "authority_mismatch".into(),
            false,
            secure,
            "本机信任的账号中心与设备网地址不一致，入站身份验证已阻断".into(),
        );
    }
    let uid = meta(K_UID);
    if uid.is_empty() || !crate::collab::authority::is_member(&uid) {
        let detail = member_warn().lock().unwrap().clone();
        return (
            "pending_local_admission".into(),
            false,
            secure,
            if detail.is_empty() {
                "账号已登记到设备网，但尚未成为本机成员；后台会继续自愈".into()
            } else {
                detail
            },
        );
    }
    if !secure {
        return (
            "insecure_legacy".into(),
            true,
            false,
            "当前账号中心仍使用明文 HTTP；互联可用，但登录凭据和设备密钥存在被窃取风险".into(),
        );
    }
    ("ready".into(), true, true, String::new())
}

/// 一轮对账。返回 (清单条数, 错误) —— 错误只用于日志/状态,不中断循环。
async fn reconcile_once() -> Result<usize, String> {
    let Some(c) = cfg() else {
        return Err("本机还没入网".into());
    };
    // 先把「自己这台机器认不认我」修好 —— 它是别的设备能不能连进来的前提。
    {
        let c2 = Cfg {
            url: c.url.clone(),
            key: c.key.clone(),
        };
        let _ = tokio::task::spawn_blocking(move || heal_local_membership(&c2)).await;
    }
    let c2 = Cfg {
        url: c.url.clone(),
        key: c.key.clone(),
    };
    let peers = tokio::task::spawn_blocking(move || announce(&c2))
        .await
        .unwrap_or_else(|e| Err(format!("报到任务失败:{e}")))?;

    let uid = meta(K_UID);
    let mut seen: Vec<String> = Vec::new();
    for p in &peers {
        let node_id = p.get("node_id").and_then(|x| x.as_str()).unwrap_or("");
        if node_id.is_empty() {
            continue;
        }
        let name = p
            .get("name")
            .and_then(|x| x.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or("同账号设备");
        seen.push(node_id.to_string());
        ensure_peer(&c, node_id, name, &uid).await;
    }
    // 本机撤销的设备:名册上可能还在(云端没踢),但本机不认 —— 立刻收回它的盘和隧道。
    // 「在别的设备上点了移出」要**当场**生效,不能等到下次重启。
    let revoked_now: Vec<String> = links()
        .lock()
        .unwrap()
        .keys()
        .filter(|k| crate::collab::grants::is_revoked(k))
        .cloned()
        .collect();
    for r in revoked_now {
        eprintln!("[mesh] 「{r}」已被本机撤销,收回盘符");
        drop_peer(&r).await;
    }
    // 名册里没了的,收回。
    let gone: Vec<String> = links()
        .lock()
        .unwrap()
        .keys()
        .filter(|k| !seen.contains(k))
        .cloned()
        .collect();
    for g in gone {
        drop_peer(&g).await;
    }
    Ok(peers.len())
}

// ────────────────────────────── 后台循环 ──────────────────────────────

fn rt() -> &'static tokio::runtime::Runtime {
    static RT: OnceLock<tokio::runtime::Runtime> = OnceLock::new();
    RT.get_or_init(|| {
        tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_name("mesh")
            .enable_all()
            .build()
            .expect("mesh runtime")
    })
}

static RUNNING: AtomicBool = AtomicBool::new(false);

/// 起后台对账循环。幂等:已在跑 = no-op(重复调 mesh_join 不会起出两个循环)。
fn spawn_loop() {
    if RUNNING.swap(true, Ordering::SeqCst) {
        return;
    }
    rt().spawn(async {
        tokio::time::sleep(FIRST_TICK).await;
        loop {
            if cfg().is_none() {
                // 已退网:收干净所有链路后停循环。
                let all: Vec<String> = links().lock().unwrap().keys().cloned().collect();
                for n in all {
                    drop_peer(&n).await;
                }
                RUNNING.store(false, Ordering::SeqCst);
                return;
            }
            match reconcile_once().await {
                Ok(n) => eprintln!("[mesh] 对账完成:名册 {n} 台"),
                Err(e) => eprintln!("[mesh] 对账失败(下一拍重试):{e}"),
            }
            tokio::time::sleep(ANNOUNCE_TICK).await;
        }
    });
}

/// 开机时如果已入网就自动接上。桌面启动流程里调一次即可 —— 用户填过一次账号之后,
/// 此后每次开机都是「打开就已经连好」。
pub fn spawn_if_enrolled() {
    if cfg().is_some() {
        eprintln!("[mesh] 已入网,后台自动接入同账号设备");
        spawn_loop();
    }
}

// ────────────────────────────── 命令 ──────────────────────────────

/// 发一枚登录验证码到邮箱。整套登录流程的第一步,也是用户唯一要动手的两步之一。
///
/// `url` 留空 = 官方云端账号中心。这个参数只为自建账号中心的人保留,UI 收在「高级」里。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn account_send_code(
    email: String,
    url: Option<String>,
    allowInsecureHttp: Option<bool>,
) -> Result<Value, String> {
    let url = validate_authority_url(&authority_of(url), allowInsecureHttp.unwrap_or(false))?;
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        agent()
            .post(&format!("{url}/api/account/send_code"))
            .send_json(json!({ "email": email.trim() }))
            .map_err(cloud_err)?;
        Ok(json!({ "sent": true }))
    })
    .await
    .map_err(|e| format!("发码任务失败:{e}"))??;
    Ok(out)
}

/// **一步登录**:邮箱 + 验证码 → 从此这台机器就在你的设备网里。
///
/// 用户只做两件事(填邮箱、填码),下面这四件事全在这一个命令里做完 ——
/// 此前它们分散在「注册页 / 登录页 / 设为主机 / 入网表单」四个地方,那正是「怎么还要登两个账号」
/// 的来源:
///   ① 拿验证码换身份断言(账号不存在就当场建号 —— 注册页因此可以整个消失);
///   ② 把这个账号中心**钉在本机**(少了它,别的设备连过来会被自己挡回去);
///   ③ 拿断言进**本机**的门,确保当前账号确实获准使用这台主机;
///   ④ 前三步都通过后才入设备网,换一把长期设备密钥并与 UID/URL 原子落库。
///
/// `inviteCode` 只在第 ③ 步真的被本机挡住时才用得上(这台机器已经有**别人**当主人了)。
/// 裸码和 `PLRS1-…` 分享码都收 —— 归一在 `authority::normalize_invite`。
///
/// 云端 enroll 或最终落库失败会直接保留在登录界面并允许重试；不会再保存一份缺 UID、
/// authority pin 或本机成员资格的“已入网”半成品。已经安全建立的本机 pin/成员关系可幂等复用。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn account_login_code(
    email: String,
    code: String,
    url: Option<String>,
    inviteCode: Option<String>,
    allowInsecureHttp: Option<bool>,
) -> Result<Value, String> {
    let url = validate_authority_url(&authority_of(url), allowInsecureHttp.unwrap_or(false))?;
    // NodeId 由本机密钥推导,不需要隧道在跑 —— 老版本那句「请先设为主机」其实是误导:
    // 真正需要主机在跑的是「别人连得进来」,不是「我拿得到身份」。所以这里不再拦人,
    // 拿不到才报错(那是密钥文件写不进去,是真问题)。
    let node_id = my_node_id();
    if node_id.is_empty() {
        return Err("本机 P2P 身份生成失败(数据目录写不进去?)—— 换个数据目录再试".into());
    }
    let invite = inviteCode.unwrap_or_default();
    let out = tokio::task::spawn_blocking({
        let url = url.clone();
        let node_id = node_id.clone();
        move || -> Result<Value, String> {
            // ① 验证码 → 身份断言(账号不存在则当场建号,由账号中心决定)。
            let resp = agent()
                .post(&format!("{url}/api/account/login_code"))
                .send_json(json!({ "email": email.trim(), "code": code.trim() }))
                .map_err(cloud_err)?;
            let v: Value = resp
                .into_json()
                .map_err(|e| format!("账号中心返回的不是 JSON:{e}"))?;
            let assertion = v
                .get("assertion")
                .and_then(|x| x.as_str())
                .ok_or("账号中心没返回身份断言 —— 确认这个地址开了 POLARIS_ACCOUNT_AUTHORITY=1")?
                .to_string();
            let email_back = v
                .get("user")
                .and_then(|u| u.get("email"))
                .and_then(|x| x.as_str())
                .unwrap_or("")
                .to_string();
            let mut out = enroll_with_assertion(&url, &node_id, &assertion, &invite, true)?;
            out["email"] = json!(email_back);
            Ok(out)
        }
    })
    .await
    .map_err(|e| format!("登录任务失败:{e}"))??;

    finish_enroll(&url, &node_id, &out)
}

/// 已有一张断言时的入网 + 进本机门。`account_login_code` 与 `mesh_join` 共用这一段,
/// 免得两条路各写一份、慢慢漂成两个语义。**阻塞**,调用方须放 spawn_blocking。
///
/// `console`=用户就坐在这台机器前亲手登的(桌面 App)。它决定第 ④ 步走哪一档准入:
/// 控制台可以认领这台机器上原有的那个账号(见 `Admission::LocalConsole`),远程递进来的
/// 断言不行。`invite` 是最后的兜底:这台机器已经有**别人**当主人时才用得上。
fn enroll_with_assertion(
    url: &str,
    node_id: &str,
    assertion: &str,
    invite: &str,
    console: bool,
) -> Result<Value, String> {
    // ② 先钉账号中心。若本机已经信任另一套 authority，必须在取得长期 meshKey 之前
    // fail closed；否则会落出“云端已入网、别的设备永远进不来”的半成品。
    crate::collab::authority::pin_explicit(url)
        .map_err(|e| format!("账号中心信任未建立，尚未入网：{e}"))?;

    // ③ 再让当前账号进本机的门。邀请码兜底也必须在 enroll 前完成；本地准入失败时
    // 用户仍停留在登录界面，可以补设备码重试，而不是拿到 meshKey 后被假成功页藏住。
    let first = if console {
        crate::collab::authority::login_with_assertion_local(assertion, node_id)
    } else {
        crate::collab::authority::login_with_assertion(assertion, node_id)
    };
    let (user, token) = match first {
        Ok(v) => v,
        Err(e) if crate::collab::authority::normalize_invite(invite).is_empty() => {
            return Err(format!("本机成员准入未完成，尚未入网：{e}"));
        }
        Err(_) => {
            crate::collab::authority::join_with_ticket(assertion, invite, &my_name(), node_id)
                .map_err(|e| format!("本机成员准入未完成，尚未入网：{e}"))?
        }
    };

    // ④ 本地两道前置闸均通过后，才去云端换长期设备密钥。
    let resp = agent()
        .post(&format!("{url}/api/mesh/enroll"))
        .send_json(json!({
            "assertion": assertion,
            "nodeId": node_id,
            "name": my_name(),
            "os": my_os(),
            "ver": my_ver(),
        }))
        .map_err(cloud_err)?;
    let v: Value = resp
        .into_json()
        .map_err(|e| format!("账号中心返回的不是 JSON:{e}"))?;
    let key = v
        .get("meshKey")
        .and_then(|x| x.as_str())
        .ok_or("账号中心没返回设备密钥")?
        .to_string();
    let uid = v
        .get("uid")
        .and_then(|x| x.as_str())
        .unwrap_or("")
        .to_string();

    Ok(json!({
        "key": key,
        "uid": uid,
        "pinWarn": "",
        "memberRole": user.role,
        "token": token,
        "memberWarn": "",
    }))
}

/// 入网成功后的落库 + 起循环。同步小操作,单独抽出来是为了让两条登录路共用同一份收尾。
fn finish_enroll(url: &str, node_id: &str, out: &Value) -> Result<Value, String> {
    let key = out["key"]
        .as_str()
        .filter(|v| !v.is_empty())
        .ok_or("入网结果缺少设备密钥，未保存登录状态")?;
    let uid = out["uid"]
        .as_str()
        .filter(|v| !v.is_empty())
        .ok_or("入网结果缺少账号 UID，未保存登录状态")?;
    crate::collab::db::meta_set_many(&[(K_URL, url), (K_KEY, key), (K_UID, uid)])?;
    spawn_loop();
    Ok(json!({
        "enrolled": true,
        "url": url,
        "uid": out["uid"],
        "email": out.get("email").cloned().unwrap_or(json!("")),
        "nodeId": node_id,
        "token": out["token"],
        // 两条「半成品」警告如实上报,UI 据此告诉用户「还差一步」而不是假装全好了:
        //  · pinWarn   :本机之前信任着**另一个**账号中心 → 别的设备连不进来;
        //  · memberWarn:这个账号还没成为本机成员(比如本机已有同名本地账号)→ 同上。
        "pinWarn": out["pinWarn"],
        "memberWarn": out["memberWarn"],
        "memberRole": out["memberRole"],
    }))
}

/// 入网地址:调用方填了就用它,没填看环境变量(server 形态),最后落到官方云机。
fn authority_of(url: Option<String>) -> String {
    url.map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(default_authority)
}

/// 拿一张**已有的**断言入网(手机壳/脚本等已经自己登过的场景)。
/// 桌面 UI 走的是 [`account_login_code`],不经过这里。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn mesh_join(
    assertion: String,
    url: Option<String>,
    inviteCode: Option<String>,
    allowInsecureHttp: Option<bool>,
) -> Result<Value, String> {
    let node_id = my_node_id();
    if node_id.is_empty() {
        return Err("本机 P2P 身份生成失败(数据目录写不进去?)—— 换个数据目录再试".into());
    }
    let url = validate_authority_url(&authority_of(url), allowInsecureHttp.unwrap_or(false))?;
    let invite = inviteCode.unwrap_or_default();
    let out = tokio::task::spawn_blocking({
        let url = url.clone();
        let node_id = node_id.clone();
        move || enroll_with_assertion(&url, &node_id, &assertion, &invite, false)
    })
    .await
    .map_err(|e| format!("入网任务失败:{e}"))??;
    finish_enroll(&url, &node_id, &out)
}

/// **设备台账**:一次给全 —— 云端目录(有哪些设备)+ 本机契约(各自什么档)+ 实时链路
/// (连上没、挂成哪个盘)。前端一个请求画完整页,不必自己 join 三份数据。
///
/// 云端拉不到(断网/云机挂了)不算失败:退回只用本机契约与实时链路画,并把原因带上 ——
/// 断网时看见「3 台设备,云端暂时联系不上」远好过看见一片空白。
#[cfg_attr(feature = "desktop", tauri::command)]
pub async fn mesh_devices() -> Result<Value, String> {
    let me = my_node_id();
    let (cloud, cloud_msg) = match cfg() {
        Some(c) => {
            let r = tokio::task::spawn_blocking(move || -> Result<Value, String> {
                let resp = agent()
                    .get(&format!("{}/api/mesh/devices", c.url))
                    .set("Authorization", &format!("Bearer {}", c.key))
                    .call()
                    .map_err(cloud_err)?;
                resp.into_json::<Value>()
                    .map_err(|e| format!("云端返回的不是 JSON:{e}"))
            })
            .await
            .unwrap_or_else(|e| Err(format!("取台账任务失败:{e}")));
            match r {
                Ok(v) => (v, String::new()),
                Err(e) => (json!({}), e),
            }
        }
        None => (json!({}), "本机还没登录".to_string()),
    };

    // 本机契约:node_id → 档位。
    let grants: HashMap<String, crate::collab::grants::Grant> = crate::collab::grants::list()
        .unwrap_or_default()
        .into_iter()
        .map(|g| (g.node_id.clone(), g))
        .collect();
    // 实时链路 + 盘。
    let mounts: HashMap<String, Value> = crate::fsmount::fs_mount_status()
        .into_iter()
        .filter_map(|v| {
            v.get("sourceId")
                .and_then(|x| x.as_str())
                .map(|s| (s.to_string(), v.clone()))
        })
        .collect();
    let links_snapshot: HashMap<String, (bool, String, String, String, u64)> = links()
        .lock()
        .unwrap()
        .iter()
        .map(|(k, l)| {
            let connected = link_connected(l);
            (
                k.clone(),
                (
                    connected,
                    l.err.clone(),
                    l.phase.clone(),
                    l.error_code.clone(),
                    l.last_verified_at,
                ),
            )
        })
        .collect();

    // 云端台账为骨架;云端拉不到就拿本机契约当骨架(断网也要能看见自己批过哪些设备)。
    let skeleton: Vec<Value> = match cloud.get("devices").and_then(|x| x.as_array()) {
        Some(list) => list.clone(),
        None => grants
            .values()
            .map(|g| {
                json!({
                    "nodeId": g.node_id, "name": g.name, "os": "", "ver": "",
                    "lastSeen": 0, "online": false, "firstSeen": g.granted_at,
                    "revoked": g.revoked, "self": g.node_id == me,
                })
            })
            .collect(),
    };

    let devices: Vec<Value> = skeleton
        .into_iter()
        .map(|mut d| {
            let nid = d
                .get("nodeId")
                .and_then(|x| x.as_str())
                .unwrap_or("")
                .to_string();
            let g = grants.get(&nid);
            let m = mounts.get(&source_id(&nid));
            let (connected, err, phase, error_code, last_verified_at) = links_snapshot
                .get(&nid)
                .cloned()
                .unwrap_or((false, String::new(), "stopped".into(), String::new(), 0));
            d["isSelf"] = json!(d.get("self").and_then(|x| x.as_bool()).unwrap_or(nid == me));
            d["connected"] = json!(connected);
            d["phase"] = json!(phase);
            d["errorCode"] = json!(error_code);
            d["lastVerifiedAt"] = json!(last_verified_at);
            d["error"] = json!(err);
            d["drive"] = m.and_then(|x| x.get("drive")).cloned().unwrap_or(json!(""));
            d["mounted"] = m.and_then(|x| x.get("ok")).cloned().unwrap_or(json!(false));
            d["writable"] = m
                .and_then(|x| x.get("writable"))
                .cloned()
                .unwrap_or(json!(false));
            // 档位:没有契约的设备(还没连过)给个「未批准」而不是编一个默认值。
            d["fsAccess"] = json!(g.map(|x| x.fs_access.clone()).unwrap_or_default());
            d["effectiveFs"] = json!(g.map(|x| x.effective_fs().to_string()).unwrap_or_default());
            d["execAccess"] = json!(g.map(|x| x.exec_access.clone()).unwrap_or_default());
            d["autoMount"] = json!(g.map(|x| x.auto_mount).unwrap_or(false));
            d["inCooldown"] = json!(g.map(|x| x.in_cooldown()).unwrap_or(false));
            d["cooldownUntil"] = json!(g.map(|x| x.cooldown_until).unwrap_or(0));
            d["granted"] = json!(g.is_some());
            d["localRevoked"] = json!(g.map(|x| x.revoked).unwrap_or(false));
            d
        })
        .collect();

    let uid = visible_uid();
    let (enrollment_state, ready, secure, enrollment_warn) = enrollment_state();
    Ok(json!({
        "enrolled": cfg().is_some(),
        "ready": ready,
        "secure": secure,
        "enrollmentState": enrollment_state,
        "enrollmentWarn": enrollment_warn,
        "url": meta(K_URL),
        "uid": uid,
        "nodeId": me,
        "name": my_name(),
        "cloudError": cloud_msg,
        // 「这台机器认不认我」。false 时别的设备一律连不进来(它们进的就是这道门),
        // UI 据此把话说明白 + 给出邀请码那条出路,而不是让用户对着一片"看得见连不上"猜。
        "localMember": crate::collab::authority::is_member(&uid),
        "localMemberWarn": member_warn().lock().unwrap().clone(),
        "devices": devices,
    }))
}

/// 改一台设备在**本机**的档位(盘 none/ro/rw、执行 none/ask/allow、自动挂载)。
///
/// 立刻落库(重启仍在),并当场生效:关掉自动挂载/降成 none 会把已挂的盘收回来,
/// 改回来则下一拍对账自动挂上 —— 不必让用户重启应用才看见效果。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn peer_grant_set(
    nodeId: String,
    fsAccess: Option<String>,
    execAccess: Option<String>,
    autoMount: Option<bool>,
) -> Result<Value, String> {
    let g = crate::collab::grants::update(
        &nodeId,
        None,
        fsAccess.as_deref(),
        execAccess.as_deref(),
        autoMount,
        "本机",
    )?;
    if !g.should_mount() {
        drop_peer(&nodeId).await;
    } else {
        // 档位变了(比如 ro→rw)要重挂才生效:writable 是挂载那一刻钉进系统的。
        drop_peer(&nodeId).await;
        let _ = mesh_sync().await;
    }
    Ok(json!({ "ok": true, "effectiveFs": g.effective_fs(), "autoMount": g.auto_mount }))
}

/// 「信任这台设备」:冷静期清零 **+ 升到全权**(顺带把误撤销的恢复回来)。
///
/// 升档这一半是设备码那条路带来的:靠码进来的设备没有冷静期,它的限制就是
/// `fs=ro / exec=none` 这两个档位本身。只清冷静期的话,用户点完按钮什么都不会变。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn peer_trust(nodeId: String) -> Result<Value, String> {
    let g = crate::collab::grants::trust_fully(&nodeId, "本机")?;
    // 冷静期里那块盘是钉死只读挂上的,清零后必须重挂才真的可写。
    drop_peer(&nodeId).await;
    let _ = mesh_sync().await;
    Ok(json!({ "ok": true, "effectiveFs": g.effective_fs() }))
}

/// 撤销一台设备在**本机**的准入,并当场收回它的盘与隧道。
///
/// 与云端的 [`mesh_kick`] 是两道独立的闸,丢了电脑应该都点:
/// 云端那道让它拿不到新断言,本机这道让它连断言都递不进来。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn peer_revoke(nodeId: String) -> Result<Value, String> {
    crate::collab::grants::revoke(&nodeId, "本机")?;
    drop_peer(&nodeId).await;
    Ok(json!({ "ok": true }))
}

/// 给设备改个人话名字(改的是云端台账,所有设备上都跟着变)。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn mesh_rename(nodeId: String, name: String) -> Result<Value, String> {
    let Some(c) = cfg() else {
        return Err("本机还没登录".into());
    };
    tokio::task::spawn_blocking(move || -> Result<(), String> {
        agent()
            .post(&format!("{}/api/mesh/rename", c.url))
            .set("Authorization", &format!("Bearer {}", c.key))
            .send_json(json!({ "nodeId": nodeId, "name": name }))
            .map_err(cloud_err)?;
        Ok(())
    })
    .await
    .map_err(|e| format!("改名任务失败:{e}"))??;
    Ok(json!({ "ok": true }))
}

/// 退网:清掉本机的设备密钥与账号 UID,拆掉所有自动挂上的盘。
/// 云端名册上这台设备仍在(只是不再报到,很快显示离线)—— 要彻底踢掉用 [`mesh_kick`]。
#[cfg_attr(feature = "desktop", tauri::command)]
pub async fn mesh_leave() -> Result<Value, String> {
    // 即使极少见的 SQLite 写入失败，也先把已挂盘和隧道收干净；错误最后如实上抛。
    let clear = crate::collab::db::meta_set_many(&[(K_KEY, ""), (K_UID, "")]);
    member_warn().lock().unwrap().clear();
    let all: Vec<String> = links().lock().unwrap().keys().cloned().collect();
    for n in all {
        drop_peer(&n).await;
    }
    clear?;
    Ok(json!({ "enrolled": false }))
}

/// 把自己账号名下的某台设备移出设备网(丢了电脑的应急操作)。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn mesh_kick(nodeId: String) -> Result<Value, String> {
    let Some(c) = cfg() else {
        return Err("本机还没入网".into());
    };
    let nid = nodeId.clone();
    tokio::task::spawn_blocking(move || -> Result<(), String> {
        agent()
            .post(&format!("{}/api/mesh/revoke", c.url))
            .set("Authorization", &format!("Bearer {}", c.key))
            .send_json(json!({ "nodeId": nid }))
            .map_err(cloud_err)?;
        Ok(())
    })
    .await
    .map_err(|e| format!("吊销任务失败:{e}"))??;
    drop_peer(&nodeId).await;
    Ok(json!({ "ok": true }))
}

/// 丢失设备的一次性安全操作：云端撤 meshKey + 本机撤准入，两条腿无论谁先失败都继续。
/// 返回 partial 供 UI 明确提示并允许重试；两边接口都幂等，重复点击不会恢复任何权限。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn mesh_device_remove(nodeId: String) -> Result<Value, String> {
    let node_id = nodeId.trim().to_string();
    if node_id.is_empty() {
        return Err("缺 NodeId".into());
    }
    if node_id == my_node_id() {
        return Err("不能从当前设备上移出当前设备；请使用退出登录".into());
    }

    let cloud = mesh_kick(node_id.clone()).await;
    let local = crate::collab::grants::revoke(&node_id, "本机");
    // 即便本地 SQLite 极少见地报错，也先拆掉当前内存链路，缩小权限窗口。
    drop_peer(&node_id).await;

    let cloud_ok = cloud.is_ok();
    let local_ok = local.is_ok();
    Ok(json!({
        "ok": cloud_ok && local_ok,
        "partial": cloud_ok != local_ok,
        "cloudRevoked": cloud_ok,
        "localRevoked": local_ok,
        "retryable": !(cloud_ok && local_ok),
        "cloudError": cloud.err().unwrap_or_default(),
        "localError": local.err().unwrap_or_default(),
    }))
}

/// 立刻对一次账(UI 点「刷新」用,不必等下一拍心跳)。
#[cfg_attr(feature = "desktop", tauri::command)]
pub async fn mesh_sync() -> Result<Value, String> {
    let n = reconcile_once().await?;
    Ok(json!({ "peers": n }))
}

// ────────────────────────── 设备码:一码互联 ──────────────────────────
//
// 「主机」这个概念到此为止。每台机器都有一串自己的码,都能被连、也都能去连别人 ——
// 界面上不再有「设为主机」「owner 令牌」「邀请码」「入伙」这些只有我们自己懂的词。
//
// 码的形态:`PLR1-<访问码>-<NodeId>`。
// 为什么 NodeId 得在码里而不是像 UU远程 那样只给一串短数字:UU 有一台云端目录服务器
// 替它把「ID → 现在在哪」查出来,我们的云端账号中心只认**同一个账号**的设备,
// 别人的账号在上面查不到你。要做成 12 位短码,得在云机上再加一张公开的
// 「码 → NodeId」目录表并重新部署它 —— 那是另一步,得你点头。现在这串码的好处是
// **不依赖云端**:两台机器都断了公网、只在一个局域网里,照样粘码就连上。

/// 本机设备码。用户复制的就是这一串。
#[cfg_attr(feature = "desktop", tauri::command)]
pub async fn device_code() -> Result<Value, String> {
    let node_id = my_node_id();
    let code = tokio::task::spawn_blocking(crate::collab::identity::access_code)
        .await
        .map_err(|e| format!("取设备码失败:{e}"))??;
    Ok(json!({
        "code": code,
        "nodeId": node_id,
        "name": my_name(),
        // NodeId 还没就绪(隧道没起来)时给半成品:UI 照实说「稍候」,别显示一串连不上的码。
        "share": if node_id.is_empty() { String::new() } else { format!("PLR1-{code}-{node_id}") },
        "ready": !node_id.is_empty(),
    }))
}

/// 换一串码:旧码当场失效,靠旧码连进来的设备会话一并作废。
#[cfg_attr(feature = "desktop", tauri::command)]
pub async fn device_code_rotate() -> Result<Value, String> {
    let code = tokio::task::spawn_blocking(|| crate::collab::identity::rotate_access_code("本机"))
        .await
        .map_err(|e| format!("换码任务失败:{e}"))??;
    let node_id = my_node_id();
    Ok(json!({
        "code": code,
        "share": if node_id.is_empty() { String::new() } else { format!("PLR1-{code}-{node_id}") },
    }))
}

/// 解析一串设备码 → (访问码, NodeId)。只认 `PLR1-<code>-<nodeId>`。
fn parse_device_code(s: &str) -> Result<(String, String), String> {
    let t = s.trim();
    if t.to_ascii_uppercase().starts_with("PLRK1-") {
        return Err("legacy_code_unsupported:这是旧版 PLRK1 设备码，缺少一次性挑战和主机密钥证明，不能安全降级使用；请让对方升级 Polaris 后重新复制 PLR1 设备码".into());
    }
    let body = t
        .strip_prefix("PLR1-")
        .or_else(|| t.strip_prefix("plr1-"))
        .ok_or("这不是设备码 —— 它长这样:PLR1-XXXXXXXX-<一串字母数字>")?;
    let (code, node) = body
        .split_once('-')
        .ok_or("设备码不完整,少了后半段 —— 让对方整串重新复制一次")?;
    if code.trim().is_empty() || node.trim().is_empty() {
        return Err("设备码不完整 —— 让对方整串重新复制一次".into());
    }
    Ok((code.trim().to_ascii_uppercase(), node.trim().to_string()))
}

/// **连对方**:粘一串码就完事 —— 起隧道 → 敲门 → 挂盘。
///
/// 与设备网那条路(同账号自动连)并行不悖:这条用于**别人的**机器,或者
/// 自己的机器但云端暂时联系不上。两条路最后落到同一个地方:一行设备契约 + 一块盘。
#[cfg_attr(feature = "desktop", tauri::command)]
pub async fn connect_by_code(code: String) -> Result<Value, String> {
    let (access, node_id) = parse_device_code(&code)?;
    if node_id == my_node_id() {
        return Err("这是你自己这台机器的码 —— 要连的是**对方**那串".into());
    }
    let port = port_for(&node_id);
    links().lock().unwrap().insert(
        node_id.clone(),
        Link {
            name: "对方设备".into(),
            port,
            token: None,
            phase: "connecting".into(),
            error_code: String::new(),
            last_verified_at: 0,
            err: String::new(),
        },
    );

    // ① 隧道(幂等)。
    #[cfg(feature = "collab-net")]
    {
        let nid = node_id.clone();
        let r =
            tokio::task::spawn_blocking(move || crate::collab::tunnel::connect_client(&nid, port))
                .await;
        if let Ok(Err(e)) = r {
            drop_peer(&node_id).await;
            return Err(format!("连不上对方(隧道建立失败):{e}"));
        }
    }
    #[cfg(not(feature = "collab-net"))]
    {
        drop_peer(&node_id).await;
        return Err("此构建没有 P2P 隧道(collab-net),连不了".into());
    }

    // ② 敲门分两步：先取一次性挑战，再用本机 host.key 证明 `me` 真是自己的 NodeId。
    // 只有设备码而没有对应私钥的人，不能冒充台账里已经升过 rw/exec 的老设备。
    let me = my_node_id();
    let my_name_s = my_name();
    let got = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let challenge_resp = agent()
            .post(&format!(
                "http://127.0.0.1:{port}/api/collab/connect/challenge"
            ))
            .send_json(json!({ "nodeId": me.clone() }))
            .map_err(|e| format!("取对方连接挑战失败(对方可能需要升级):{}", cloud_err(e)))?;
        let challenge_body: Value = challenge_resp
            .into_json()
            .map_err(|e| format!("对方连接挑战不是 JSON:{e}"))?;
        let challenge = challenge_body["challenge"]
            .as_str()
            .filter(|s| !s.is_empty())
            .ok_or("对方没返回连接挑战 —— 请先升级对方的 Polaris")?;
        let signature = crate::collab::identity::sign_connect_proof(&me, &access, challenge)?;

        let resp = agent()
            .post(&format!("http://127.0.0.1:{port}/api/collab/connect"))
            .send_json(json!({
                "code": access,
                "nodeId": me,
                "challenge": challenge,
                "signature": signature,
                "name": my_name_s,
                "os": my_os(),
                "ver": my_ver(),
            }))
            .map_err(cloud_err)?;
        resp.into_json::<Value>()
            .map_err(|e| format!("对方返回的不是 JSON:{e}"))
    })
    .await
    .unwrap_or_else(|e| Err(format!("敲门任务失败:{e}")));
    let v = match got {
        Ok(v) => v,
        Err(e) => {
            drop_peer(&node_id).await;
            return Err(e);
        }
    };
    let token = v["token"].as_str().unwrap_or_default().to_string();
    if token.is_empty() {
        drop_peer(&node_id).await;
        return Err("对方没给会话令牌 —— 它可能是个还没升级的老版本".into());
    }

    // ③ 挂盘。对方给的是只读就挂只读 —— 挂成读写再让用户撞一鼻子灰是最糟的选择。
    let ro = v["fsAccess"].as_str().unwrap_or("ro") != crate::collab::grants::FS_RW;
    let name = v["peerName"]
        .as_str()
        .filter(|s| !s.is_empty())
        .unwrap_or("对方设备")
        .to_string();
    let mounted = crate::fsmount::fs_mount(
        source_id(&node_id),
        name.clone(),
        node_id.clone(),
        port,
        token.clone(),
        Some(ro),
        None,
    )
    .await;
    {
        let mount_ok = mounted
            .as_ref()
            .ok()
            .and_then(|v| v.get("ok"))
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let mut map = links().lock().unwrap();
        if let Some(l) = map.get_mut(&node_id) {
            l.name = name.clone();
            l.token = Some(token);
            l.phase = if mount_ok {
                "ready"
            } else if mounted.is_ok() {
                "mounting"
            } else {
                "degraded"
            }
            .into();
            l.error_code = if mounted.is_ok() {
                String::new()
            } else {
                "mount_failed".into()
            };
            l.last_verified_at = now_secs();
            l.err = mounted.as_ref().err().cloned().unwrap_or_default();
        }
    }
    Ok(json!({
        "ok": true,
        "nodeId": node_id,
        "name": name,
        "readOnly": ro,
        "note": v["note"],
        "drive": mounted.as_ref().ok().and_then(|x| x["drive"].as_str()).unwrap_or(""),
        "mountError": mounted.err().unwrap_or_default(),
    }))
}

/// 设备网现状:入网了吗、名册上有谁、各自连上了没、挂成了哪块盘。
#[cfg_attr(feature = "desktop", tauri::command)]
pub fn mesh_status() -> Value {
    let enrolled = cfg().is_some();
    let (enrollment_state, ready, secure, enrollment_warn) = enrollment_state();
    // fsmount 的实况(盘符/读写档/在线)按 sourceId 对进来,前端一处就能全画出来。
    let mounts: HashMap<String, Value> = crate::fsmount::fs_mount_status()
        .into_iter()
        .filter_map(|v| {
            v.get("sourceId")
                .and_then(|x| x.as_str())
                .map(|s| (s.to_string(), v.clone()))
        })
        .collect();
    let peers: Vec<Value> = links()
        .lock()
        .unwrap()
        .iter()
        .map(|(node_id, l)| {
            let m = mounts.get(&source_id(node_id));
            json!({
                "nodeId": node_id,
                "name": l.name,
                "port": l.port,
                "connected": link_connected(l),
                "phase": l.phase,
                "errorCode": l.error_code,
                "lastVerifiedAt": l.last_verified_at,
                "error": l.err,
                // 对端会话 token 交给前端:远程终端(/api/exec)与「浏览盘」都靠它。
                // 与手工添加的远程源同一口径 —— 那条路的 owner 令牌本来就存在前端。
                "token": l.token.clone().unwrap_or_default(),
                "drive": m.and_then(|x| x.get("drive")).cloned().unwrap_or(json!("")),
                "writable": m.and_then(|x| x.get("writable")).cloned().unwrap_or(json!(false)),
                "ok": m.and_then(|x| x.get("ok")).cloned().unwrap_or(json!(false)),
            })
        })
        .collect();
    json!({
        "enrolled": enrolled,
        "ready": ready,
        "secure": secure,
        "enrollmentState": enrollment_state,
        "enrollmentWarn": enrollment_warn,
        "url": meta(K_URL),
        "uid": visible_uid(),
        "nodeId": my_node_id(),
        "name": my_name(),
        "peers": peers,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn url_normalization_prefers_https_and_public_http_requires_consent() {
        assert_eq!(norm_url(" example.com/ "), "https://example.com");
        assert_eq!(norm_url("https://a.com/"), "https://a.com");
        assert_eq!(norm_url("http://a.com"), "http://a.com");
        assert!(validate_authority_url("http://a.com", false)
            .unwrap_err()
            .contains("明文 HTTP"));
        assert_eq!(
            validate_authority_url("http://a.com", true).unwrap(),
            "http://a.com"
        );
        assert_eq!(
            validate_authority_url("http://127.0.0.1:8080", false).unwrap(),
            "http://127.0.0.1:8080"
        );
    }

    #[test]
    fn device_code_parser_requires_the_complete_plr1_shape() {
        let (code, node) = parse_device_code("plr1-abcd2345-node-identity").unwrap();
        assert_eq!(code, "ABCD2345");
        assert_eq!(node, "node-identity");
        assert!(parse_device_code("ABCD2345").is_err());
        assert!(parse_device_code("PLR1-ABCD2345").is_err());
        assert!(parse_device_code("PLR1--node").is_err());
        assert!(parse_device_code("PLRK1-old-owner-token")
            .unwrap_err()
            .starts_with("legacy_code_unsupported:"));
    }

    #[test]
    fn logged_out_status_never_exposes_a_stale_uid() {
        assert_eq!(current_uid(false, "uid-from-old-login".into()), "");
        assert_eq!(current_uid(true, "uid-current".into()), "uid-current");
    }

    #[test]
    fn cached_token_without_a_live_tunnel_is_not_connected() {
        let link = Link {
            name: "stale".into(),
            port: 65_534,
            token: Some("cached-session".into()),
            phase: "ready".into(),
            error_code: String::new(),
            last_verified_at: now_secs(),
            err: String::new(),
        };
        assert!(
            !link_connected(&link),
            "刚验证过的 token 也不能把不存在的 tunnel 冒充成在线"
        );
    }

    /// sourceId 必须稳定且不超长(fsmount 拿它当 key,长 NodeId 截断后仍要唯一到实用)。
    #[test]
    fn source_id_is_stable_and_short() {
        let a = "abcdefghijklmnopqrstuvwxyz0123456789";
        assert_eq!(source_id(a), source_id(a));
        assert_eq!(source_id(a), "mesh-abcdefghijklmnop");
        assert_eq!(source_id("short"), "mesh-short");
    }

    /// 端口分配:新设备各得一口,已在册的沿用原口(重试不换口)。
    #[test]
    fn ports_are_unique_and_sticky() {
        links().lock().unwrap().clear();
        let p1 = port_for("node-a");
        links().lock().unwrap().insert(
            "node-a".into(),
            Link {
                name: "a".into(),
                port: p1,
                token: None,
                phase: "connecting".into(),
                error_code: String::new(),
                last_verified_at: 0,
                err: String::new(),
            },
        );
        let p2 = port_for("node-b");
        assert_ne!(p1, p2, "两台设备不能撞同一个本地口");
        assert_eq!(port_for("node-a"), p1, "已在册的必须沿用原端口");
        links().lock().unwrap().clear();
    }
}
//! 桌面「把这台电脑设为主机」:进程内嵌 axum,只挂协作端点(/api/collab/*、/git/*、/ws、/api/health)。
//! 不碰 kb/chat 等模块 —— 它们已由桌面 setup 初始化,这里只是给同事开一扇协作门。
//!
//! 端口:默认从 8484 起扫到 8494(避开 8080 —— Docker Desktop/wslrelay 常把
//! localhost:8080 的 IPv6 侧占掉,踩过「连到别人家服务」的坑)。
//! 事件:内嵌服务有自己的 broadcast 频道(远端成员走 /ws 收);另起桥接任务把
//! 事件转发给本机 Tauri UI(主机人自己的看板实时刷新)。
#![cfg(feature = "desktop")]

use crate::apihub::{api_router, ApiState};
use crate::collab::http::{collab_router, detect_advertise_urls, CollabState};
use crate::host::AppHandle as BusHandle;
use parking_lot::Mutex;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::sync::Arc;

const PORT_SCAN: std::ops::Range<u16> = 8484..8495;

struct Running {
    /// 启动代次:每次 start 单调递增。占位与转正/回滚都比对代次,防 ABA——
    /// A 启动中被 stop 摘走占位、B 立即重启插入新占位后,A 完成时若只认「是占位」
    /// 就会认领 B 的占位(A 复活/B 自毁、旧 Child 被 drop 成孤儿)。
    gen: u64,
    port: u16,
    urls: Vec<String>,
    shutdown: Option<tokio::sync::oneshot::Sender<()>>,
    /// axum serve 任务句柄:stop 时先给优雅窗口,超时 abort(drop listener 释放端口)。
    /// 只发 oneshot 不收尸的话,/ws 长连接会让 graceful shutdown 永远等不完 →
    /// 旧 serve 僵尸占 8484,再 start 落到 8485 双服务并存,反复停/开逐次泄漏端口。
    serve_task: Option<tokio::task::JoinHandle<()>>,
    /// 事件桥任务句柄(bridge_to_ui):stop 时 abort,防残留任务攒一批订阅者。
    bridge_task: Option<tauri::async_runtime::JoinHandle<()>>,
    /// tauri→bus 的对话流单向桥监听 id:stop 时 unlisten,防重复 start 累积监听。
    chat_bridge: Option<tauri::EventId>,
    /// 存一份 tauri 句柄仅为 stop 时能 unlisten 上面的 chat_bridge。
    app: tauri::AppHandle,
    /// 从不读取,纯 keep-alive:随 Running 一起 drop 时 broadcast 关闭,各 ws_loop 收尾。
    #[allow(dead_code)]
    bus: BusHandle,
    /// 仅经 Tauri IPC 返回给本机 UI，用于首次 bootstrap；绝不挂在 HTTP 路由上。
    access_token: String,
}

static RUNNING: Mutex<Option<Running>> = Mutex::new(None);

#[derive(Serialize, Deserialize, Clone, Copy, Default)]
struct HostCfg {
    enabled: bool,
    port: Option<u16>,
    /// 允许 LAN/Tailscale 直连(绑 0.0.0.0)。打包版双击启动拿不到环境变量,
    /// 所以除 POLARIS_HOST_ALLOW_LAN 外也认这份持久化配置;数据面仍有口令/会话闸。
    #[serde(default)]
    allow_lan: bool,
}

fn cfg_path() -> Option<PathBuf> {
    directories::UserDirs::new().map(|u| u.home_dir().join("Polaris/data/collab_host.json"))
}

fn load_cfg() -> HostCfg {
    cfg_path()
        .and_then(|p| std::fs::read_to_string(p).ok())
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_default()
}

fn save_cfg(c: HostCfg) {
    if let Some(p) = cfg_path() {
        if let Some(dir) = p.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        let _ = std::fs::write(p, serde_json::to_string(&c).unwrap_or_default());
    }
}

fn random_access_token() -> Result<String, String> {
    use std::fmt::Write as _;
    let mut bytes = [0u8; 32];
    getrandom::getrandom(&mut bytes).map_err(|e| format!("生成主机访问口令失败: {e}"))?;
    let mut token = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        let _ = write!(&mut token, "{byte:02x}");
    }
    Ok(token)
}

/// 本机 iroh 主机 NodeId(手机据此打洞 P2P 直连);未启用 collab-net 时为空串。
fn host_iroh_node_id() -> String {
    #[cfg(feature = "collab-net")]
    {
        crate::collab::tunnel::host_node_id().unwrap_or_default()
    }
    #[cfg(not(feature = "collab-net"))]
    {
        String::new()
    }
}

fn lan_access_enabled() -> bool {
    // 环境变量显式设置时优先(可强制关);未设置则看持久化配置。
    match std::env::var("POLARIS_HOST_ALLOW_LAN") {
        Ok(v) => v == "1" || v.eq_ignore_ascii_case("true"),
        Err(_) => load_cfg().allow_lan,
    }
}

/// 内核启动(不依赖 tauri,可单测):绑端口 → 建独立事件频道 → 起 axum(graceful shutdown)。
/// 返回 serve 任务的 JoinHandle:stop 侧靠它「优雅窗口 + 超时 abort」确认端口真正释放。
#[allow(clippy::type_complexity)]
pub async fn start_core(
    pref_port: Option<u16>,
    api_app: Option<tauri::AppHandle>,
) -> Result<
    (
        u16,
        Vec<String>,
        BusHandle,
        String,
        tokio::sync::oneshot::Sender<()>,
        tokio::task::JoinHandle<()>,
    ),
    String,
> {
    let (tx, _rx) = tokio::sync::broadcast::channel::<crate::host::Event>(4096);
    // tx 需要克隆:一份包成 BusHandle 给 collab 事件面,一份给应用数据面 ApiState.tx 供 /ws 订阅。
    let bus = BusHandle::new(tx.clone());
    let configured_token = std::env::var("POLARIS_AUTH_TOKEN")
        .ok()
        .filter(|s| !s.trim().is_empty());
    let access_token = match configured_token {
        Some(token) => token,
        None => random_access_token()?,
    };
    let auth_token = Some(access_token.clone());

    // 绑定地址:默认只绑 loopback(127.0.0.1)。远端成员经 iroh 隧道入内 —— 隧道有设备白名单,
    // 且把流量转发到本机 127.0.0.1(见 tunnel.rs upstream_addr),loopback 绑定对隧道零影响。
    // 这样同网段的人**无法直连**该端口打到裸明文 HTTP(此前 0.0.0.0 + 未初始化协作会兜底成 owner,
    // 等于对局域网敞开一个 owner 权限的裸接口)。
    // 想让 LAN 内不经隧道、按 IP 直连入伙 → 显式 POLARIS_HOST_ALLOW_LAN=1。即使管理员
    // 没有配置固定口令，本次进程也会生成 256-bit 随机口令，避免裸露 owner 接口。
    let allow_lan = lan_access_enabled();
    let bind_ip: &str = if allow_lan { "0.0.0.0" } else { "127.0.0.1" };

    let mut cands: Vec<u16> = Vec::new();
    if let Some(p) = pref_port {
        cands.push(p);
    }
    cands.extend(PORT_SCAN);
    let mut bound = None;
    for p in cands {
        if let Ok(l) = tokio::net::TcpListener::bind((bind_ip, p)).await {
            bound = Some((l, p));
            break;
        }
    }
    let (listener, port) = bound.ok_or("端口 8484-8494 全被占用,请释放一个再试")?;
    // 把真实端口告知隧道:此前隧道默认转发 8080 而内嵌服务在 8484-8494,
    // 未设 POLARIS_TUNNEL_UPSTREAM 时远端流量会打进黑洞。
    #[cfg(feature = "collab-net")]
    crate::collab::tunnel::set_upstream_port(port);
    let urls = detect_advertise_urls(port);

    // 口令 Arc 在 collab 面与应用数据面之间共享(同一把口令,同一份鉴权语义)。
    let auth_arc = Arc::new(auth_token);
    let state = CollabState {
        app: bus.clone(),
        auth_token: auth_arc.clone(),
        advertise: Arc::new(parking_lot::RwLock::new(urls.clone())),
    };
    // 有 tauri 句柄时挂应用数据面(invoke/upload/file/ws),让远端(手机/中继网关)拿到
    // 与 Docker server 壳一致的完整能力;此时 /ws 由 api_router 统一提供,collab 面不再
    // 单独挂 /ws(否则路由重叠 panic)—— api 的 ws_handler 订阅同一条 bus,collab 事件照收。
    let with_collab_ws = api_app.is_none();
    let mut router = collab_router(state, with_collab_ws)
        .route("/api/health", axum::routing::get(|| async { "ok" }));
    if let Some(app) = api_app {
        let api_state = ApiState {
            app,
            tx: tx.clone(),
            auth_token: auth_arc.clone(),
            // 恒 false:桌面主机的入场券是分享码里那把口令(上面 access_token),它就在
            // 分享码里、用户复制粘贴即得,不存在「忘了被锁死」的问题,故不走 Docker 那套
            // 免口令。远端成员还经 iroh 隧道转到本机 127.0.0.1,来源判定也认不出谁是谁。
            open_no_auth: false,
        };
        router = router.merge(api_router(api_state.clone()));
        // 应用直投的「粘性回退」:被代理应用页面里的绝对路径(/assets/x.js、/socket.io/…)
        // 不带 /app/{slug} 前缀,靠进门时种的 cookie 认回属于哪个应用。桌面壳根路径本来
        // 就没挂东西(前端是 tauri webview,不由这里托管),接管它零冲突;
        // Docker server 壳根上有 SPA(server.rs 已占 fallback),故这条只在桌面挂。
        let sticky: axum::Router = axum::Router::new().fallback(crate::appproxy::sticky_fallback);
        router = router.merge(sticky);
    }
    // 分享码探活 + 成员端 REST 都是跨源 → CORS 必开。普通 JSON 限 2MB；/api/upload
    // 在 api_router 内单独放宽到 512MB;git 路由在 collab_router 内单独放宽。
    let router = router
        .layer(axum::extract::DefaultBodyLimit::max(2 * 1024 * 1024))
        .layer(tower_http::cors::CorsLayer::permissive());

    // 远程文件浏览(fsface)开放根:设了 POLARIS_FS_ROOTS 才亮,提醒运维已把盘暴露给隧道对端。
    let fs_roots = crate::collab::fsface::roots();
    if !fs_roots.is_empty() {
        eprintln!("[fsface] 远程浏览已开放,根: {fs_roots:?}");
    }

    let (stx, srx) = tokio::sync::oneshot::channel::<()>();
    let serve_task = tokio::spawn(async move {
        let _ = axum::serve(listener, router)
            .with_graceful_shutdown(async {
                let _ = srx.await;
            })
            .await;
    });
    Ok((port, urls, bus, access_token, stx, serve_task))
}

/// 「启动中」占位(port=0 为标记):在 start_core(...).await **之前**原子占住 RUNNING,
/// 堵并发 start(autostart 与手点)在 await 窗口期双起并覆盖旧 Running —— 一旦覆盖,
/// 旧的 chat_bridge 监听 / bridge_task / serve_task 句柄全丢 = 永久泄漏。
/// bus 是临时哑频道,转正时整体替换;真实端口永远落在 8484-8494,port=0 不会撞。
static NEXT_GEN: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

fn starting_placeholder(app: tauri::AppHandle, gen: u64) -> Running {
    Running {
        gen,
        port: 0,
        urls: Vec::new(),
        shutdown: None,
        serve_task: None,
        bridge_task: None,
        chat_bridge: None,
        app,
        bus: BusHandle::new(tokio::sync::broadcast::channel(1).0),
        access_token: String::new(),
    }
}

/// 内嵌主机当前实际绑定的端口(未跑 / 启动占位期 = None)。
pub fn current_port() -> Option<u16> {
    RUNNING.lock().as_ref().map(|r| r.port).filter(|p| *p != 0)
}

/// 往内嵌主机的广播总线投一条事件(桌面 → 手机/中继的**唯一**出口)。
///
/// 返回是否真投出去了:主机没跑(或还在启动占位期)时总线只是个哑频道,投进去无人接 ——
/// 此时如实返回 false,让调用方能提示「还没设为主机,对端收不到」,而不是假装发出去了。
/// 注:总线上的事件会被 [`bridge_to_ui`] 回灌本机 tauri 事件系统,故调用方**不必**再本地 emit
/// 一遍,否则本机 UI 会收到两条一模一样的帧。
pub fn bus_emit(topic: &str, payload: serde_json::Value) -> bool {
    let g = RUNNING.lock();
    match g.as_ref() {
        Some(r) if r.port != 0 => {
            r.bus.emit_value(topic, payload);
            true
        }
        _ => false,
    }
}

fn status_json() -> serde_json::Value {
    let g = RUNNING.lock();
    // is_bootstrap()==true 表示还没有任何账号 → 前端应引导「初始化」而非「登录」。
    let needs_bootstrap = crate::collab::auth::is_bootstrap().unwrap_or(true);
    match g.as_ref() {
        // port=0 是「启动中占位」:还没真跑起来,按未运行上报(前端稍后轮询即见真状态)。
        Some(r) if r.port == 0 => serde_json::json!({
            "running": false, "starting": true, "port": 0, "urls": [],
            "needsBootstrap": needs_bootstrap, "autostart": load_cfg().enabled,
            "accessToken": "",
            "remoteAccess": false,
        }),
        Some(r) => serde_json::json!({
            "running": true, "port": r.port, "urls": r.urls,
            "needsBootstrap": needs_bootstrap, "autostart": load_cfg().enabled,
            "accessToken": r.access_token,
            "remoteAccess": lan_access_enabled(),
            "nodeId": host_iroh_node_id(),
        }),
        None => serde_json::json!({
            "running": false, "port": 0, "urls": [],
            "needsBootstrap": needs_bootstrap, "autostart": load_cfg().enabled,
            "accessToken": "",
            "remoteAccess": false,
        }),
    }
}

/// 事件桥:内嵌服务的广播 → 本机 Tauri UI(主机人自己的看板实时刷新)。
/// Lagged(积压超容被跳帧)必须 continue 而不是退出 —— `while let Ok(..)` 会在第一次
/// Lagged 时整个循环永久死亡,主机本机看板从此不再实时刷新且无任何报错
///(远端成员走 /ws 的 ws_loop 早已是 Lagged=>continue 的正确写法,这里对齐)。
fn bridge_to_ui(app: tauri::AppHandle, bus: &BusHandle) -> tauri::async_runtime::JoinHandle<()> {
    let mut rx = bus.subscribe();
    tauri::async_runtime::spawn(async move {
        use tauri::Emitter;
        use tokio::sync::broadcast::error::RecvError;
        loop {
            match rx.recv().await {
                Ok(ev) => {
                    // chat:stream 由桌面 chat_send 直接 tauri emit 给本机 webview;bus 上的
                    // chat:stream 是 bridge_chat_to_bus 专为远端灌入的,若再 emit 回 tauri 会
                    // 与该桥形成回环(tauri→bus→tauri→…)。故本机 UI 桥跳过它。
                    if ev.topic == "chat:stream" {
                        continue;
                    }
                    let _ = app.emit(&ev.topic, ev.payload);
                }
                Err(RecvError::Lagged(n)) => {
                    eprintln!("[collab-host] UI 事件桥积压,跳过 {n} 条旧事件(继续转发)");
                    continue;
                }
                Err(RecvError::Closed) => break, // 主机已停,频道关闭 → 正常收工
            }
        }
    })
}

/// 对话流单向桥:桌面 chat_send 把 `chat:stream` emit 到 tauri 事件系统(直达本机
/// webview),这里 `listen` 捕获后再灌进内嵌主机的广播 bus → api_router 的 /ws 推给
/// 远端(手机/中继网关)。这样对话逐字流既到本机 UI、也到远端,而 chat_send/pipeline
/// 一行不改。返回监听 id,stop 时 unlisten。
fn bridge_chat_to_bus(app: &tauri::AppHandle, bus: &BusHandle) -> tauri::EventId {
    use tauri::Listener;
    let bus = bus.clone();
    app.listen("chat:stream", move |event| {
        // event.payload() 是已序列化的 JSON 串;解析回 Value 再进 bus。走 emit_value 直通
        // (泛型 emit 对 Value 入参会经 to_value 整树深拷贝一遍),Event 构造时预序列化一次
        // WS 帧,N 条远端连接共享 —— 逐字流热路径全程只有「1 次解析 + 1 次序列化」。
        if let Ok(v) = serde_json::from_str::<serde_json::Value>(event.payload()) {
            bus.emit_value("chat:stream", v);
        }
    })
}

#[tauri::command]
pub async fn collab_host_start(
    app: tauri::AppHandle,
    port: Option<u16>,
) -> Result<serde_json::Value, String> {
    // ── 原子占位:检查与插入在同一把锁内完成。旧写法「检查通过 → start_core(...).await
    //    → 才插 RUNNING」中间隔着整个绑端口/建路由,并发 start 双起且互相覆盖 Running。
    let my_gen = NEXT_GEN.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    {
        let mut g = RUNNING.lock();
        if g.is_some() {
            drop(g);
            return Ok(status_json()); // 幂等:已在跑/正在启动就报状态
        }
        *g = Some(starting_placeholder(app.clone(), my_gen));
    }
    // 端口 0 消毒:配置里若残留 Some(0),bind(ip, 0) 会成功绑到随机端口并把「0」当真实
    // 端口上报,还与占位哨兵(port==0)撞车 —— stop 会把真服务当占位摘走造成泄漏。
    let pref = port.or(load_cfg().port).filter(|p| *p != 0);
    // 传入 tauri 句柄 → start_core 挂应用数据面(invoke/upload/file/ws);对话流经
    // bridge_chat_to_bus 灌进 bus 供远端 /ws。
    let (port, urls, bus, access_token, stx, serve_task) =
        match start_core(pref, Some(app.clone())).await {
            Ok(v) => v,
            Err(e) => {
                // 启动失败 → 回滚**自己那个代次**的占位。占位可能已被 stop 摘走、甚至
                // 已被更晚的 start 换成新占位(ABA)—— 只认 gen,绝不误删别人的。
                let mut g = RUNNING.lock();
                if g.as_ref()
                    .map(|r| r.port == 0 && r.gen == my_gen)
                    .unwrap_or(false)
                {
                    *g = None;
                }
                return Err(e);
            }
        };
    let bridge_task = bridge_to_ui(app.clone(), &bus);
    let chat_bridge = bridge_chat_to_bus(&app, &bus);
    // ── 转正:占位还在才写入。占位已被 collab_host_stop 摘走 = 启动窗口期间用户点了
    //    停止 → 立刻收掉刚起的这套(shutdown + abort + unlisten),不留泄漏、不改配置。
    let mut fresh = Some(Running {
        gen: my_gen,
        port,
        urls,
        shutdown: Some(stx),
        serve_task: Some(serve_task),
        bridge_task: Some(bridge_task),
        chat_bridge: Some(chat_bridge),
        app,
        bus,
        access_token,
    });
    {
        let mut g = RUNNING.lock();
        if let Some(r) = g.as_mut() {
            // 只认领自己代次的占位:占位被 stop 摘走后又被新 start 占上时(ABA),
            // 认领别人的占位=被停掉的实例复活+新实例自毁。
            if r.port == 0 && r.gen == my_gen {
                *r = fresh.take().expect("fresh 尚未被取走");
            }
        }
    }
    if let Some(f) = fresh {
        // 未转正 → 收掉刚起的这套栈,与 stop 同款优雅窗口(超时 abort 确保端口真正释放)。
        if let Some(s) = f.shutdown {
            let _ = s.send(());
        }
        if let Some(bt) = f.bridge_task {
            bt.abort();
        }
        if let Some(id) = f.chat_bridge {
            use tauri::Listener;
            f.app.unlisten(id);
        }
        if let Some(mut h) = f.serve_task {
            if tokio::time::timeout(std::time::Duration::from_secs(2), &mut h)
                .await
                .is_err()
            {
                h.abort();
                let _ = tokio::time::timeout(std::time::Duration::from_secs(1), &mut h).await;
            }
        }
        return Ok(status_json());
    }
    // ── iroh 主机隧道:桌面当主机时也起 host_listen,让手机经 iroh 打洞 P2P 连进来
    //    (打洞失败自动走 n0 relay 兜底)。手机 probeEntry 拿到主机 nodeId + 原生隧道可用
    //    → 优先起隧道直连桌面,而不是走裸地址。host_listen 有设备白名单硬闸。
    #[cfg(feature = "collab-net")]
    {
        if !crate::collab::tunnel::is_running() {
            crate::collab::tunnel::start_host_blocking_thread();
        }
    }
    save_cfg(HostCfg {
        enabled: true,
        port: Some(port),
        ..load_cfg()
    });
    Ok(status_json())
}

#[tauri::command]
pub fn collab_host_status() -> serde_json::Value {
    status_json()
}

/// 授权一台设备(把它的 iroh NodeId 加进白名单)。iroh host_listen 只放行白名单里的
/// NodeId —— 手机首次经 iroh 连本机前,owner 在「互联」把手机显示的 NodeId 加进来即可。
/// 幂等:已在白名单则直接返回成功。owner 级(经 tauri 命令,本机可信)。
#[tauri::command]
#[allow(non_snake_case)]
pub fn collab_host_add_device(name: String, nodeId: String) -> Result<(), String> {
    let nid = nodeId.trim();
    if nid.is_empty() || nid.len() > 256 || nid.chars().any(char::is_control) {
        return Err("设备 NodeId 无效".into());
    }
    if crate::collab::identity::is_node_allowed(nid) {
        return Ok(());
    }
    let nm = if name.trim().is_empty() {
        "我的设备"
    } else {
        name.trim()
    };
    crate::collab::identity::add_device(0, nm, nid).map(|_| ())
}

/// 切换「允许局域网 / Tailscale 直连」(绑 0.0.0.0)。持久化到 collab_host.json;主机在跑
/// 则重启以按新地址重绑,让 status 的 urls 带上局域网 IP —— 手机据此才够得着这台桌面主机。
/// 关掉则回绑 127.0.0.1(只本机可连,最安全)。数据面仍有口令/会话闸,不裸露 owner 接口。
#[tauri::command]
pub async fn collab_host_set_remote_access(
    app: tauri::AppHandle,
    enabled: bool,
) -> Result<serde_json::Value, String> {
    // 环境变量显式设置时优先于持久化配置(见 lan_access_enabled)→ UI 改不动,明确告知。
    if std::env::var("POLARIS_HOST_ALLOW_LAN").is_ok() {
        return Err("局域网访问由环境变量 POLARIS_HOST_ALLOW_LAN 固定,无法在此切换".into());
    }
    let mut cfg = load_cfg();
    cfg.allow_lan = enabled;
    save_cfg(cfg);
    // 主机在跑 → 停后重启,按新 bind_ip(0.0.0.0 / 127.0.0.1)重新绑定地址。
    let was_running = RUNNING.lock().is_some();
    if was_running {
        collab_host_stop().await?;
        collab_host_start(app, None).await
    } else {
        Ok(status_json())
    }
}

#[tauri::command]
pub async fn collab_host_stop() -> Result<serde_json::Value, String> {
    // ① 只取走信号与任务句柄,先不清 RUNNING:优雅窗口期间保持「运行中」,
    //    让并发的 start 走幂等分支返回,而不是抢先绑到 8485 造成双服务。
    //    (parking_lot 锁不能跨 await 持有 → 取出后立刻放锁。)
    let (shutdown, serve_task, bridge_task, chat_bridge, app) = {
        let mut g = RUNNING.lock();
        // 「启动中占位」(port=0):还没有任何真实句柄可收,直接摘掉占位即可 ——
        // in-flight 的 collab_host_start 转正时发现占位已消失,会自行收掉刚起的栈。
        if g.as_ref().map(|r| r.port == 0).unwrap_or(false) {
            *g = None;
            drop(g);
            save_cfg(HostCfg {
                enabled: false,
                ..load_cfg()
            });
            return Ok(status_json());
        }
        match g.as_mut() {
            Some(r) => (
                r.shutdown.take(),
                r.serve_task.take(),
                r.bridge_task.take(),
                r.chat_bridge.take(),
                Some(r.app.clone()),
            ),
            None => (None, None, None, None, None),
        }
    };
    // ② 发 graceful shutdown 信号(停止 accept 新连接)。
    if let Some(s) = shutdown {
        let _ = s.send(());
    }
    // ③ 事件桥是纯转发循环,直接 abort;对话流桥 unlisten(防重复 start 累积监听)。
    if let Some(bt) = bridge_task {
        bt.abort();
    }
    if let (Some(app), Some(id)) = (app, chat_bridge) {
        use tauri::Listener;
        app.unlisten(id);
    }
    // ④ 优雅窗口:graceful shutdown 会等所有在途连接结束,而 /ws 是长连接永不结束
    //    → 最多等 2s,超时就 abort(drop listener + 连接,端口立即释放),
    //    再短等 1s 确认任务真正退出。否则旧 serve 僵尸占 8484,stop 后立即 start
    //    只能落到 8485,反复停/开会把 8484-8494 逐个泄漏光。
    if let Some(mut h) = serve_task {
        if tokio::time::timeout(std::time::Duration::from_secs(2), &mut h)
            .await
            .is_err()
        {
            h.abort();
            let _ = tokio::time::timeout(std::time::Duration::from_secs(1), &mut h).await;
        }
    }
    // ⑤ 全部确认退出后才清 RUNNING(顺带 drop bus → broadcast 关闭 → 各 ws_loop 收
    //    Closed 自行收尾)。stop 返回后立即 start 能重新绑回 8484。
    *RUNNING.lock() = None;
    save_cfg(HostCfg {
        enabled: false,
        ..load_cfg()
    });
    Ok(status_json())
}

/// App 启动时自动拉起(上次开过主机就续上,别让同事早上连不上)。
/// 走与手点完全相同的 collab_host_start 入口:同一套「原子占位 → 转正/回滚」防线,
/// 自启与手点并发时只会有一方真正起服务,另一方幂等返回,不再双起覆盖泄漏。
pub fn auto_start_if_enabled(app: tauri::AppHandle) {
    let cfg = load_cfg();
    if !cfg.enabled {
        return;
    }
    tauri::async_runtime::spawn(async move {
        match collab_host_start(app, cfg.port).await {
            Ok(s) => println!(
                "[collab-host] 主机自启成功,端口 {}",
                s.get("port").and_then(|v| v.as_u64()).unwrap_or(0)
            ),
            Err(e) => eprintln!("[collab-host] 主机自启失败: {e}"),
        }
    });
}

