static LEAD_AI_RUNNING: Lazy<parking_lot::Mutex<HashSet<i64>>> =
    Lazy::new(|| parking_lot::Mutex::new(HashSet::new()));

struct LeadAiRunGuard(i64);

impl LeadAiRunGuard {
    fn acquire(project_id: i64) -> Result<Self, String> {
        let mut running = LEAD_AI_RUNNING.lock();
        if !running.insert(project_id) {
            return Err("该项目已有一个主 Agent 请求在运行，请等待完成后重试".into());
        }
        Ok(Self(project_id))
    }
}

impl Drop for LeadAiRunGuard {
    fn drop(&mut self) {
        LEAD_AI_RUNNING.lock().remove(&self.0);
    }
}

/// 协作面状态:与 server::AppState 解耦,桌面内嵌时独立构造。
#[derive(Clone)]
pub struct CollabState {
    /// 事件广播壳(server 壳与其 AppState.app 同源;桌面 hosting 独立频道)
    pub app: AppHandle,
    /// 全局访问口令(POLARIS_AUTH_TOKEN);None = 未设
    pub auth_token: Arc<Option<String>>,
    /// 票据分享码携带的「本机可达地址」(http://ip:port),外壳启动时注入
    pub advertise: Arc<parking_lot::RwLock<Vec<String>>>,
}

/// 探测本机可对外通告的地址。优先 POLARIS_ADVERTISE_URL(逗号分隔,给反代/固定域名用);
/// 否则 UDP connect 技巧取「默认路由出口 IP」与「Tailscale 口 IP」(connect 不发包,零依赖)。
pub fn detect_advertise_urls(port: u16) -> Vec<String> {
    let mut out = Vec::new();
    if let Ok(v) = std::env::var("POLARIS_ADVERTISE_URL") {
        for s in v.split(',') {
            let s = s.trim();
            if !s.is_empty() {
                out.push(s.trim_end_matches('/').to_string());
            }
        }
        if !out.is_empty() {
            return out;
        }
    }
    let probe = |target: &str| -> Option<std::net::IpAddr> {
        let s = std::net::UdpSocket::bind("0.0.0.0:0").ok()?;
        s.connect(target).ok()?;
        s.local_addr().ok().map(|a| a.ip())
    };
    let mut ips: Vec<std::net::IpAddr> = Vec::new();
    if let Some(ip) = probe("8.8.8.8:80") {
        ips.push(ip); // 默认路由(局域网/公网口)
    }
    if let Some(ip) = probe("100.100.100.100:80") {
        if !ips.contains(&ip) {
            ips.push(ip); // Tailscale 口(100.64/10 路由存在才命中)
        }
    }
    for ip in ips {
        if !ip.is_loopback() && !is_tun_fake_ip(&ip) {
            out.push(format!("http://{ip}:{port}"));
        }
    }
    out
}

/// 198.18.0.0/15 是基准测试保留段,被 Clash/Surge 等 TUN 代理拿来当 fake-ip。
/// 开着 TUN 时「默认路由出口 IP」探到的就是它;把它通告进连接码,对方(往往也开着
/// TUN)连它会回环到**对方自己**的 Polaris,表现为 401/串机迷惑 —— 一律不通告。
fn is_tun_fake_ip(ip: &std::net::IpAddr) -> bool {
    matches!(ip, std::net::IpAddr::V4(v) if v.octets()[0] == 198 && (v.octets()[1] & 0xfe) == 18)
}

// ───────────────────────── 鉴权 ─────────────────────────

/// 一次请求的鉴权结果:是谁、什么角色。
#[derive(Clone)]
pub struct AuthCtx {
    pub user_id: i64, // 0 = 合成身份(全局口令 admin / 本机单人 local)
    pub username: String,
    pub role: String, // owner|collaborator|visitor|lead
    /// 这条请求是**哪台设备**发来的(会话上记的 device_id;全局口令等合成身份为空)。
    /// 盘与远程执行的按设备闸靠它 —— 见 `grants::fs_gate` / `grants::exec_gate`。
    pub device_id: String,
}

pub fn bearer_of(headers: &HeaderMap) -> Option<String> {
    headers
        .get("authorization")
        .and_then(|v| v.to_str().ok())
        .map(|s| s.strip_prefix("Bearer ").unwrap_or(s).to_string())
        .or_else(|| {
            headers
                .get("x-polaris-token")
                .and_then(|v| v.to_str().ok())
                .map(|s| s.to_string())
        })
}

/// 「这台机器处于免口令模式，且**这一条请求**的来源够格」——由外壳(server.rs)按它
/// 自己那套来源判定算好，经请求扩展塞进来。没有这个扩展(桌面内嵌主机 / 老调用方)
/// 一律当 false。
///
/// 只有 [`collab_bootstrap`] 读它：免口令的 NAS 上机器根本没有口令可出示，
/// 不认这条闸就永远建不出第一个账号 —— 协作/团队整条线直接锁死。
/// 其余端点照旧只认真会话，`resolve_auth` 也绝不因此合成 owner。
#[derive(Clone, Copy, Debug)]
pub struct OpenGate(pub bool);

/// token(header 或 ws query) → AuthCtx。None = 未授权。
pub fn resolve_auth(auth_token: &Option<String>, token: Option<&str>) -> Option<AuthCtx> {
    // 轨② 全局口令 = owner。
    if let Some(expected) = auth_token.as_ref() {
        if token == Some(expected.as_str()) {
            return Some(AuthCtx {
                user_id: 0,
                username: "admin".into(),
                role: "owner".into(),
                device_id: String::new(),
            });
        }
    }
    // 轨① 会话 token。
    if let Some(t) = token {
        if let Ok((u, device_id)) = crate::collab::auth::check_session_with_device(t) {
            return Some(AuthCtx {
                user_id: u.id,
                username: u.username,
                role: u.role,
                device_id,
            });
        }
    }
    // 未命中就拒绝。零账号/无全局口令也绝不能合成 owner：否则攻击者可先调用
    // owner-only 的票据接口，再 redeem 绕过 bootstrap 初始化口令。
    None
}

/// header → AuthCtx。鉴权的同步 SQLite 查询挪进阻塞线程池:直接跑在 axum async worker
/// 上会钉住 reactor(会话短缓存命中时不落库,这层 spawn_blocking 兜的是未命中/首次)。
pub async fn auth_ctx(state: &CollabState, headers: &HeaderMap) -> Option<AuthCtx> {
    let auth_token = state.auth_token.clone();
    let token = bearer_of(headers);
    tokio::task::spawn_blocking(move || resolve_auth(&auth_token, token.as_deref()))
        .await
        .ok()
        .flatten()
}

/// 盘的入方向闸:**角色**或**设备契约**,两条路任一通过即可。
///
/// 为什么不能只留角色闸:设备码那条路进来的是 visitor,角色闸(owner 级)会把它一刀切死,
/// 「拿码就能连、默认只读」根本走不通。为什么不能只留契约闸:桌面自己、owner 令牌、
/// 老手机壳走的会话没有设备契约,只认契约会把它们全挡在外面。
///
/// 判定顺序:**先看契约**(它是用户在台账上亲手调的档,优先级最高,连 owner 角色也压得住 ——
/// 冷静期里的自己人也该只读),契约没话说才退回角色闸。
fn fs_allowed(ctx: &AuthCtx, need_write: bool) -> Result<(), String> {
    crate::collab::grants::fs_gate(&ctx.device_id, need_write)?;
    // 契约放行了,还要够角色 —— 除非它本来就是被契约放进来的那种设备。
    if role_rank(&ctx.role) >= 3 || has_grant(&ctx.device_id) {
        return Ok(());
    }
    Err("需要 owner 权限".into())
}

/// 这台设备有没有一行信任契约(有 = 它是经「设备码 / 同账号设备网」正式放进来的)。
fn has_grant(device_id: &str) -> bool {
    !device_id.trim().is_empty()
        && matches!(crate::collab::grants::get(device_id), Ok(Some(g)) if !g.revoked)
}

pub fn role_rank(role: &str) -> u8 {
    match role {
        "owner" => 3,
// ───────────────────────── 同账号设备网 /api/mesh/*(权威侧)─────────────────────────
//
// 「登录同一个账号 → 设备自己成网」的目录服务。只有账号权威(云机)提供;成员主机上这些
// 路由一律 400,与 /api/account/* 同口径。
//
// 鉴权是**设备密钥**(不是会话):Bearer mk_… 由 /api/mesh/enroll 颁发。理由是设备网的
// 心跳跑在后台、跨天跨重启,不该依赖某个会话的寿命;而它能做的事只有三样(报到、取本账号
// 设备清单、换一张 5 分钟身份断言),换不到任何一台设备的访问权。

/// 设备密钥入口闸。密钥无效/被吊销 → 403 并带上原因(客户端据此决定「重新入网」)。
fn mesh_key_of(headers: &HeaderMap) -> Result<String, Response> {
    bearer_of(headers).ok_or_else(|| {
        (
            StatusCode::UNAUTHORIZED,
            Json(json!({"error":"缺设备密钥(Bearer mk_…)"})),
        )
            .into_response()
    })
}

/// 设备入网:拿一张身份断言换一把长期设备密钥。
///
/// 断言由本机(权威)自己签的,所以这里用**自己的公钥**验 —— 等于确认「这张断言真是我签的、
/// 没过期」。客户端的断言来自 `/api/account/login`,即用户刚亲自输过密码。
async fn mesh_enroll(Json(v): Json<Value>) -> Response {
    if !crate::collab::authority::is_authority() {
        return not_authority();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        use crate::collab::authority as A;
        let claims = A::verify_assertion_with(&s_of(&v, "assertion"), &A::public_key_b64()?)?;
        let key = crate::collab::mesh::enroll(
            &claims.uid,
            &s_of(&v, "nodeId"),
            &s_of(&v, "name"),
            &s_of(&v, "os"),
            &s_of(&v, "ver"),
        )?;
        Ok(json!({ "meshKey": key, "uid": claims.uid, "username": claims.username }))
    })
    .await;
    unwrap_api(out)
}

/// 心跳 + 取同账号设备清单(一次往返办两件事)。
async fn mesh_announce(headers: HeaderMap, Json(v): Json<Value>) -> Response {
    if !crate::collab::authority::is_authority() {
        return not_authority();
    }
    let key = match mesh_key_of(&headers) {
        Ok(k) => k,
        Err(r) => return r,
    };
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let (uid, peers) = crate::collab::mesh::announce(
            &key,
            &s_of(&v, "name"),
            &s_of(&v, "os"),
            &s_of(&v, "ver"),
        )?;
        Ok(json!({ "uid": uid, "peers": peers }))
    })
    .await;
    unwrap_api(out)
}

/// 设备密钥 → 一张新的 5 分钟身份断言。设备拿它去**对端主机**换本机会话。
///
/// 这是设备网唯一的「凭据升级」点,也是它必须只能自助的原因:签出来的断言只说
/// 「我是 uid X」,进不进得去某台机器仍由那台机器自己的成员资格决定。
async fn mesh_assert(headers: HeaderMap) -> Response {
    if !crate::collab::authority::is_authority() {
        return not_authority();
    }
    let key = match mesh_key_of(&headers) {
        Ok(k) => k,
        Err(r) => return r,
    };
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let (uid, _) = crate::collab::mesh::resolve_key(&key)?;
        let (username, email, display) = crate::collab::mesh::account_of(&uid)?;
        let assertion =
            crate::collab::authority::sign_assertion(&uid, &username, &email, &display)?;
        Ok(json!({ "assertion": assertion, "uid": uid, "username": username }))
    })
    .await;
    unwrap_api(out)
}

/// 设备**台账**:这个账号名下的全部设备(含自己那台、含已移出的)。
///
/// 与 announce 回的名册的分工:那个是给后台对账循环用的「我该连谁」,这个是给人看的。
/// 台账少一台都是缺陷 —— 用户要认出「哪台是我正用的」,也要看见「上周被我踢掉的那台」。
async fn mesh_devices(headers: HeaderMap) -> Response {
    if !crate::collab::authority::is_authority() {
        return not_authority();
    }
    let key = match mesh_key_of(&headers) {
        Ok(k) => k,
        Err(r) => return r,
    };
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let (uid, me) = crate::collab::mesh::resolve_key(&key)?;
        let list: Vec<Value> = crate::collab::mesh::devices(&uid)?
            .into_iter()
            .map(|(p, revoked)| {
                json!({
                    "nodeId": p.node_id, "name": p.name, "os": p.os, "ver": p.ver,
                    "lastSeen": p.last_seen, "online": p.online, "firstSeen": p.first_seen,
                    "revoked": revoked,
                    // 「这台就是你现在坐着的这台」——台账上要标出来,不然一屋子机器名认不出谁是谁。
                    "self": p.node_id == me,
                })
            })
            .collect();
        Ok(json!({ "uid": uid, "nodeId": me, "devices": list }))
    })
    .await;
    unwrap_api(out)
}

/// 给自己账号名下的设备改个人话名字。改过之后心跳不再用机器名覆盖它。
async fn mesh_rename(headers: HeaderMap, Json(v): Json<Value>) -> Response {
    if !crate::collab::authority::is_authority() {
        return not_authority();
    }
    let key = match mesh_key_of(&headers) {
        Ok(k) => k,
        Err(r) => return r,
    };
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let (uid, _) = crate::collab::mesh::resolve_key(&key)?;
        crate::collab::mesh::rename(&uid, &s_of(&v, "nodeId"), &s_of(&v, "name"))?;
        Ok(json!({ "ok": true }))
    })
    .await;
    unwrap_api(out)
}

