//! 多人协作 HTTP 路由 —— 双壳共用(Docker server 壳 merge;桌面 hosting 内嵌)。
//!
//! 从 server.rs 整体迁入(逻辑零改动,只把状态从 AppState 换成 CollabState):
//! 鉴权胶水(AuthCtx/resolve_auth/角色闸)+ 全部 /api/collab/* handler + /git/* 反代
//! + WS 推流循环。server 壳经 `collab_router(state, false)` merge 复用;桌面
//! 「一键当主机」(collab/hosting.rs)经 `collab_router(state, true)` 内嵌并自带 /ws。
//!
//! 双轨鉴权(向后兼容):
//!  ① 多用户会话(collab):token 命中 sessions 表 → 得到具体用户与角色,命令过角色闸。
//!  ② 传统全局口令 POLARIS_AUTH_TOKEN:命中即视为 owner(机器管理员,单人 Docker 场景)。
//!  协作启用后(users 表非空)未带任何有效凭据 → 拒绝;未启用协作则维持旧语义。

use crate::host::{AppHandle, Event};
use axum::{
    body::Body,
    extract::{ws::Message, ws::WebSocket, Query, State, WebSocketUpgrade},
    http::{header, HeaderMap, StatusCode},
    response::{IntoResponse, Response},
    routing::{get, post},
    Json, Router,
};
use base64::Engine;
use futures_util::{SinkExt, StreamExt};
use once_cell::sync::Lazy;
use serde::Serialize;
use serde_json::{json, Value};
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::broadcast;

static LEAD_AI_RUNNING: Lazy<parking_lot::Mutex<HashSet<i64>>> =
    Lazy::new(|| parking_lot::Mutex::new(HashSet::new()));

struct LeadAiRunGuard(i64);

impl LeadAiRunGuard {
    fn acquire(project_id: i64) -> Result<Self, String> {
        let mut running = LEAD_AI_RUNNING.lock();
        if !running.insert(project_id) {
            return Err("该项目已有一个主 Agent 请求在运行，请等待完成后重试".into());
        }
        Ok(Self(project_id))
    }
}

impl Drop for LeadAiRunGuard {
    fn drop(&mut self) {
        LEAD_AI_RUNNING.lock().remove(&self.0);
    }
}

/// 协作面状态:与 server::AppState 解耦,桌面内嵌时独立构造。
#[derive(Clone)]
pub struct CollabState {
    /// 事件广播壳(server 壳与其 AppState.app 同源;桌面 hosting 独立频道)
    pub app: AppHandle,
    /// 全局访问口令(POLARIS_AUTH_TOKEN);None = 未设
    pub auth_token: Arc<Option<String>>,
    /// 票据分享码携带的「本机可达地址」(http://ip:port),外壳启动时注入
    pub advertise: Arc<parking_lot::RwLock<Vec<String>>>,
}

/// 探测本机可对外通告的地址。优先 POLARIS_ADVERTISE_URL(逗号分隔,给反代/固定域名用);
/// 否则 UDP connect 技巧取「默认路由出口 IP」与「Tailscale 口 IP」(connect 不发包,零依赖)。
pub fn detect_advertise_urls(port: u16) -> Vec<String> {
    let mut out = Vec::new();
    if let Ok(v) = std::env::var("POLARIS_ADVERTISE_URL") {
        for s in v.split(',') {
            let s = s.trim();
            if !s.is_empty() {
                out.push(s.trim_end_matches('/').to_string());
            }
        }
        if !out.is_empty() {
            return out;
        }
    }
    let probe = |target: &str| -> Option<std::net::IpAddr> {
        let s = std::net::UdpSocket::bind("0.0.0.0:0").ok()?;
        s.connect(target).ok()?;
        s.local_addr().ok().map(|a| a.ip())
    };
    let mut ips: Vec<std::net::IpAddr> = Vec::new();
    if let Some(ip) = probe("8.8.8.8:80") {
        ips.push(ip); // 默认路由(局域网/公网口)
    }
    if let Some(ip) = probe("100.100.100.100:80") {
        if !ips.contains(&ip) {
            ips.push(ip); // Tailscale 口(100.64/10 路由存在才命中)
        }
    }
    for ip in ips {
        if !ip.is_loopback() && !is_tun_fake_ip(&ip) {
            out.push(format!("http://{ip}:{port}"));
        }
    }
    out
}

/// 198.18.0.0/15 是基准测试保留段,被 Clash/Surge 等 TUN 代理拿来当 fake-ip。
/// 开着 TUN 时「默认路由出口 IP」探到的就是它;把它通告进连接码,对方(往往也开着
/// TUN)连它会回环到**对方自己**的 Polaris,表现为 401/串机迷惑 —— 一律不通告。
fn is_tun_fake_ip(ip: &std::net::IpAddr) -> bool {
    matches!(ip, std::net::IpAddr::V4(v) if v.octets()[0] == 198 && (v.octets()[1] & 0xfe) == 18)
}

// ───────────────────────── 鉴权 ─────────────────────────

/// 一次请求的鉴权结果:是谁、什么角色。
#[derive(Clone)]
pub struct AuthCtx {
    pub user_id: i64, // 0 = 合成身份(全局口令 admin / 本机单人 local)
    pub username: String,
    pub role: String, // owner|collaborator|visitor|lead
    /// 这条请求是**哪台设备**发来的(会话上记的 device_id;全局口令等合成身份为空)。
    /// 盘与远程执行的按设备闸靠它 —— 见 `grants::fs_gate` / `grants::exec_gate`。
    pub device_id: String,
}

pub fn bearer_of(headers: &HeaderMap) -> Option<String> {
    headers
        .get("authorization")
        .and_then(|v| v.to_str().ok())
        .map(|s| s.strip_prefix("Bearer ").unwrap_or(s).to_string())
        .or_else(|| {
            headers
                .get("x-polaris-token")
                .and_then(|v| v.to_str().ok())
                .map(|s| s.to_string())
        })
}

/// 「这台机器处于免口令模式，且**这一条请求**的来源够格」——由外壳(server.rs)按它
/// 自己那套来源判定算好，经请求扩展塞进来。没有这个扩展(桌面内嵌主机 / 老调用方)
/// 一律当 false。
///
/// 只有 [`collab_bootstrap`] 读它：免口令的 NAS 上机器根本没有口令可出示，
/// 不认这条闸就永远建不出第一个账号 —— 协作/团队整条线直接锁死。
/// 其余端点照旧只认真会话，`resolve_auth` 也绝不因此合成 owner。
#[derive(Clone, Copy, Debug)]
pub struct OpenGate(pub bool);

/// token(header 或 ws query) → AuthCtx。None = 未授权。
pub fn resolve_auth(auth_token: &Option<String>, token: Option<&str>) -> Option<AuthCtx> {
    // 轨② 全局口令 = owner。
    if let Some(expected) = auth_token.as_ref() {
        if token == Some(expected.as_str()) {
            return Some(AuthCtx {
                user_id: 0,
                username: "admin".into(),
                role: "owner".into(),
                device_id: String::new(),
            });
        }
    }
    // 轨① 会话 token。
    if let Some(t) = token {
        if let Ok((u, device_id)) = crate::collab::auth::check_session_with_device(t) {
            return Some(AuthCtx {
                user_id: u.id,
                username: u.username,
                role: u.role,
                device_id,
            });
        }
    }
    // 未命中就拒绝。零账号/无全局口令也绝不能合成 owner：否则攻击者可先调用
    // owner-only 的票据接口，再 redeem 绕过 bootstrap 初始化口令。
    None
}

/// header → AuthCtx。鉴权的同步 SQLite 查询挪进阻塞线程池:直接跑在 axum async worker
/// 上会钉住 reactor(会话短缓存命中时不落库,这层 spawn_blocking 兜的是未命中/首次)。
pub async fn auth_ctx(state: &CollabState, headers: &HeaderMap) -> Option<AuthCtx> {
    let auth_token = state.auth_token.clone();
    let token = bearer_of(headers);
    tokio::task::spawn_blocking(move || resolve_auth(&auth_token, token.as_deref()))
        .await
/// 断言不行。`invite` 是最后的兜底:这台机器已经有**别人**当主人时才用得上。
fn enroll_with_assertion(
    url: &str,
    node_id: &str,
    assertion: &str,
    invite: &str,
    console: bool,
) -> Result<Value, String> {
    // ② 先钉账号中心。若本机已经信任另一套 authority，必须在取得长期 meshKey 之前
    // fail closed；否则会落出“云端已入网、别的设备永远进不来”的半成品。
    crate::collab::authority::pin_explicit(url)
        .map_err(|e| format!("账号中心信任未建立，尚未入网：{e}"))?;

    // ③ 再让当前账号进本机的门。邀请码兜底也必须在 enroll 前完成；本地准入失败时
    // 用户仍停留在登录界面，可以补设备码重试，而不是拿到 meshKey 后被假成功页藏住。
    let first = if console {
        crate::collab::authority::login_with_assertion_local(assertion, node_id)
    } else {
        crate::collab::authority::login_with_assertion(assertion, node_id)
    };
    let (user, token) = match first {
        Ok(v) => v,
        Err(e) if crate::collab::authority::normalize_invite(invite).is_empty() => {
            return Err(format!("本机成员准入未完成，尚未入网：{e}"));
        }
        Err(_) => {
            crate::collab::authority::join_with_ticket(assertion, invite, &my_name(), node_id)
                .map_err(|e| format!("本机成员准入未完成，尚未入网：{e}"))?
        }
    };

    // ④ 本地两道前置闸均通过后，才去云端换长期设备密钥。
    let resp = agent()
        .post(&format!("{url}/api/mesh/enroll"))
        .send_json(json!({
            "assertion": assertion,
            "nodeId": node_id,
            "name": my_name(),
            "os": my_os(),
            "ver": my_ver(),
        }))
        .map_err(cloud_err)?;
    let v: Value = resp
        .into_json()
        .map_err(|e| format!("账号中心返回的不是 JSON:{e}"))?;
    let key = v
        .get("meshKey")
        .and_then(|x| x.as_str())
        .ok_or("账号中心没返回设备密钥")?
        .to_string();
    let uid = v
        .get("uid")
        .and_then(|x| x.as_str())
        .unwrap_or("")
        .to_string();

    Ok(json!({
        "key": key,
        "uid": uid,
        "pinWarn": "",
        "memberRole": user.role,
        "token": token,
        "memberWarn": "",
    }))
}

/// 入网成功后的落库 + 起循环。同步小操作,单独抽出来是为了让两条登录路共用同一份收尾。
fn finish_enroll(url: &str, node_id: &str, out: &Value) -> Result<Value, String> {
    let key = out["key"]
        .as_str()
        .filter(|v| !v.is_empty())
        .ok_or("入网结果缺少设备密钥，未保存登录状态")?;
    let uid = out["uid"]
        .as_str()
        .filter(|v| !v.is_empty())
        .ok_or("入网结果缺少账号 UID，未保存登录状态")?;
    crate::collab::db::meta_set_many(&[(K_URL, url), (K_KEY, key), (K_UID, uid)])?;
    spawn_loop();
    Ok(json!({
        "enrolled": true,
        "url": url,
        "uid": out["uid"],
        "email": out.get("email").cloned().unwrap_or(json!("")),
        "nodeId": node_id,
        "token": out["token"],
        // 两条「半成品」警告如实上报,UI 据此告诉用户「还差一步」而不是假装全好了:
        //  · pinWarn   :本机之前信任着**另一个**账号中心 → 别的设备连不进来;
        //  · memberWarn:这个账号还没成为本机成员(比如本机已有同名本地账号)→ 同上。
        "pinWarn": out["pinWarn"],
        "memberWarn": out["memberWarn"],
        "memberRole": out["memberRole"],
    }))
}

/// 入网地址:调用方填了就用它,没填看环境变量(server 形态),最后落到官方云机。
fn authority_of(url: Option<String>) -> String {
    url.map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(default_authority)
}

/// 拿一张**已有的**断言入网(手机壳/脚本等已经自己登过的场景)。
/// 桌面 UI 走的是 [`account_login_code`],不经过这里。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn mesh_join(
    assertion: String,
    url: Option<String>,
    inviteCode: Option<String>,
    allowInsecureHttp: Option<bool>,
) -> Result<Value, String> {
    let node_id = my_node_id();
    if node_id.is_empty() {
        return Err("本机 P2P 身份生成失败(数据目录写不进去?)—— 换个数据目录再试".into());
    }
    let url = validate_authority_url(&authority_of(url), allowInsecureHttp.unwrap_or(false))?;
    let invite = inviteCode.unwrap_or_default();
    let out = tokio::task::spawn_blocking({
        let url = url.clone();
        let node_id = node_id.clone();
        move || enroll_with_assertion(&url, &node_id, &assertion, &invite, false)
    })
    .await
    .map_err(|e| format!("入网任务失败:{e}"))??;
    finish_enroll(&url, &node_id, &out)
}

