// ── Endpoint 惰性初始化 ─────────────────────────────────────────────────────

async fn ensure_endpoint() -> Result<Endpoint, String> {
    let mut g = ENDPOINT.lock().await;
    if let Some(ep) = g.as_ref() {
        return Ok(ep.clone());
    }
    let seed = get_or_create_gateway_key()?;
    let transport = QuicTransportConfig::builder()
        .keep_alive_interval(KEEP_ALIVE)
        .max_idle_timeout(Some(
            IdleTimeout::try_from(IDLE_TIMEOUT).expect("idle timeout 常量合法"),
        ))
        .build();
    let ep = Endpoint::builder(presets::N0)
        .secret_key(SecretKey::from_bytes(&seed))
        .transport_config(transport)
        .alpns(vec![ALPN.to_vec()])
        .bind()
        .await
        .map_err(|e| format!("网关 iroh endpoint 绑定失败: {e}"))?;
    *g = Some(ep.clone());
    eprintln!("[gateway] iroh Endpoint 就绪 node_id={}", ep.id());
    Ok(ep)
}

/// 取一条到指定主机的健康连接:缓存里已死的丢弃重建。
async fn healthy_conn(host_node_id: &str) -> Result<Connection, String> {
    if let Some(c) = CONNS.read().get(host_node_id).cloned() {
        if c.close_reason().is_none() {
            return Ok(c);
        }
        .await
        .ok()
        .flatten()
}

/// 盘的入方向闸:**角色**或**设备契约**,两条路任一通过即可。
///
/// 为什么不能只留角色闸:设备码那条路进来的是 visitor,角色闸(owner 级)会把它一刀切死,
/// 「拿码就能连、默认只读」根本走不通。为什么不能只留契约闸:桌面自己、owner 令牌、
/// 老手机壳走的会话没有设备契约,只认契约会把它们全挡在外面。
///
/// 判定顺序:**先看契约**(它是用户在台账上亲手调的档,优先级最高,连 owner 角色也压得住 ——
/// 冷静期里的自己人也该只读),契约没话说才退回角色闸。
fn fs_allowed(ctx: &AuthCtx, need_write: bool) -> Result<(), String> {
    crate::collab::grants::fs_gate(&ctx.device_id, need_write)?;
    // 契约放行了,还要够角色 —— 除非它本来就是被契约放进来的那种设备。
    if role_rank(&ctx.role) >= 3 || has_grant(&ctx.device_id) {
        return Ok(());
    }
    Err("需要 owner 权限".into())
}

/// 这台设备有没有一行信任契约(有 = 它是经「设备码 / 同账号设备网」正式放进来的)。
fn has_grant(device_id: &str) -> bool {
    !device_id.trim().is_empty()
        && matches!(crate::collab::grants::get(device_id), Ok(Some(g)) if !g.revoked)
}

pub fn role_rank(role: &str) -> u8 {
    match role {
        "owner" => 3,
        "lead" | "collaborator" => 2,
        "visitor" => 1,
        _ => 0,
    }
}

