        crate::collab::gateway::unregister_user(id);
        let username = crate::collab::auth::delete_user(id)?;
        crate::collab::db::audit(&actor, "user.delete", &username, "owner 远程删号");
        Ok(json!({"ok": true, "username": username}))
    })
    .await;
    unwrap_api(out)
}

